class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  std::array<float, 8> bands{}, base{}, goal{}, seeds{}, power{};
  float phase = 0, crackle = 0;
  Random rng{3};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    bands.fill(0);
    power.fill(0);
    for (int i = 0; i < 8; i++) {
      base[i] = rng.unit() * 6.2831853f;
      goal[i] = base[i];
      seeds[i] = rng.unit() * 10.0f;
    }
    phase = rng.unit() * 10.0f;
    crackle = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    bool strike = hit > kick + 0.2f;
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));

    static const int edges[9] = {0, 3, 6, 9, 13, 17, 21, 26, 31};
    for (int b = 0; b < 8; b++) {
      float v = 0;
      for (int i = edges[b]; i < edges[b + 1]; i++) v = std::max(v, m.smoothSpectrum[i]);
      bands[b] = follow(bands[b], v, 22.0f, 4.0f, dt);
    }

    for (int i = 0; i < 8; i++) {
      // Tres filamentos siempre vivos; el resto aparece con su banda.
      float target = (i < 4 ? 0.5f : 0.0f) + bands[i] * 1.1f + kick * (i < 6 ? 0.7f : 0.4f);
      power[i] = follow(power[i], target, 25.0f, 5.0f, dt);
      // El golpe fija un destino nuevo y el rayo se desliza hasta él en
      // unas décimas de segundo, como un latigazo continuo.
      if (strike) goal[i] += (rng.unit() - 0.5f) * 2.2f;
      goal[i] += dt * f.speed * (i % 2 ? 1.0f : -1.0f) * (0.08f + 0.25f * drive);
      base[i] += (goal[i] - base[i]) * (1.0f - std::exp(-dt * 9.0f));
    }
    phase += dt * f.speed * (0.6f + 1.4f * drive + 0.6f * kick);
    // Reloj propio del chisporroteo: cambia de forma continua, sin parpadeo.
    crackle += dt * (1.6f + 2.4f * spark);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::array<float, 8> angle{};
    for (int i = 0; i < 8; i++) angle[i] = base[i] + std::sin(phase * 0.35f + seeds[i]) * 0.45f;
    std::vector<float> u;
    u.reserve(44);
    u.insert(u.end(), {phase, bass * amp, kick * amp, energy});
    u.insert(u.end(), {angle[0], angle[1], angle[2], angle[3]});
    u.insert(u.end(), {angle[4], angle[5], angle[6], angle[7]});
    for (int i = 0; i < 8; i++) u.push_back(std::min(power[i] * amp, 2.0f));
    u.insert(u.end(), {spark * amp, flash, f.glow, crackle});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("plasma", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.plasma:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;     // tiempo, graves, golpe, energía
uniform vec4 uAng0;
uniform vec4 uAng1;
uniform vec4 uPow0;
uniform vec4 uPow1;
uniform vec4 uM;     // agudos, destello, glow, reloj del chisporroteo
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

// Desvío lateral suave del rayo a lo largo de su recorrido (s = 0..1).
float wander(float s, float len, float seed) {
  float t = uA.x;
  float env = sin(3.14159 * s) * (0.55 + 0.45 * s);
  float amp = min(len, 0.7);
  return (sin(s * 6.0 + t * 1.3 + seed * 5.0) * 0.09 + sin(s * 15.0 - t * 2.7 + seed * 11.0) * 0.035) * amp * env;
}

// Rayo de plasma desde `origin` en la dirección `dir`; devuelve (núcleo, halo).
// Lejos del rayo sólo se calcula su halo; la forma y el chisporroteo se
// evalúan cerca, con una transición suave entre ambos cálculos.
vec2 bolt(vec2 p, vec2 origin, vec2 dir, float len, float power, float seed, float width0) {
  vec2 nrm = vec2(-dir.y, dir.x);
  vec2 q = p - origin;
  float along = dot(q, dir);
  float lat0 = dot(q, nrm);
  float beyond = along < 0.0 ? -along : max(along - len, 0.0);
  float reach = 0.13 * min(len, 0.7);
  float k = 0.00005 + 0.0001 * power;
  if (abs(lat0) > reach + 0.2 || beyond > 0.2) {
    return vec2(0.0, k / (lat0 * lat0 + beyond * beyond + 0.0004) * power);
  }
  float s = clamp(along / len, 0.0, 1.0);
  float smoothLat = lat0 - wander(s, len, seed);
  float lateral = smoothLat;
  if (abs(smoothLat) < 0.06) {
    float env = sin(3.14159 * s);
    lateral -= (noise(vec2(s * 40.0 + seed * 3.0, uM.w)) - 0.5) * (0.035 + 0.09 * uM.x) * min(len, 0.7) * env;
  }
  float blend = smoothstep(reach + 0.08, reach + 0.2, abs(lat0));
  float haloLat = mix(smoothLat, lat0, blend);
  float inside = step(0.0, along) * step(along, len);
  float width = (width0 + 0.005 * min(power, 1.5)) * (1.0 - 0.5 * s);
  float core = exp(-lateral * lateral / (width * width)) * inside;
  float halo = k / (haloLat * haloLat + beyond * beyond + 0.0004);
  return vec2(core * 1.5 * power, halo * power);
}

// Rayo principal hasta el borde de la pantalla, con una rama.
vec2 tendril(vec2 p, float ang, float power, float seed, vec2 halfSize) {
  if (power < 0.02) return vec2(0.0);
  vec2 dir = vec2(cos(ang), sin(ang));
  float len = min(halfSize.x / max(abs(dir.x), 0.001), halfSize.y / max(abs(dir.y), 0.001)) * 1.02;
  vec2 acc = bolt(p, vec2(0.0), dir, len, power, seed, 0.004);
  // Punto de contacto con el borde: la descarga ilumina donde toca.
  vec2 tip = dir * len;
  acc.x += exp(-dot(p - tip, p - tip) / (0.0012 + 0.002 * power)) * power;
  if (power > 0.35) {
    float fork = 0.42 + 0.2 * fract(seed * 0.37);
    vec2 nrm = vec2(-dir.y, dir.x);
    vec2 origin = dir * len * fork + nrm * wander(fork, len, seed);
    float side = fract(seed * 0.61) < 0.5 ? -1.0 : 1.0;
    float ba = ang + side * (0.45 + 0.25 * sin(uA.x * 0.7 + seed));
    vec2 bdir = vec2(cos(ba), sin(ba));
    acc += bolt(p, origin, bdir, len * 0.45, power * 0.7, seed + 7.0, 0.0025) * 0.8;
  }
  return acc;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  p.y = -p.y;
  vec2 halfSize = 0.5 * uSize / scale;
  float r = length(p);
  float kick = uA.z;
  float t = uA.x;

  // Gas eléctrico en toda la pantalla, más vivo con la música y el golpe.
  float gas = noise(p * 2.2 + vec2(t * 0.12, -t * 0.08));
  vec3 col = uC0 + mix(uC2, uC1, gas) * gas * (0.006 + 0.03 * uA.w + 0.12 * kick) * uM.z;
  col += mix(uC1, uC2, 0.5) * exp(-r * r * 2.5) * (0.015 + 0.04 * uA.w + 0.2 * kick);

  vec2 acc = vec2(0.0);
  acc += tendril(p, uAng0.x, uPow0.x, 0.0, halfSize);
  acc += tendril(p, uAng0.y, uPow0.y, 1.7, halfSize);
  acc += tendril(p, uAng0.z, uPow0.z, 3.1, halfSize);
  acc += tendril(p, uAng0.w, uPow0.w, 4.6, halfSize);
  acc += tendril(p, uAng1.x, uPow1.x, 6.2, halfSize);
  acc += tendril(p, uAng1.y, uPow1.y, 7.9, halfSize);
  acc += tendril(p, uAng1.z, uPow1.z, 9.3, halfSize);
  acc += tendril(p, uAng1.w, uPow1.w, 10.8, halfSize);
  vec3 arc = mix(uC1, uC3, clamp(acc.x * 0.55, 0.0, 1.0)) * acc.x + mix(uC2, uC1, 0.4) * acc.y * (0.9 + 0.7 * kick);
  col += arc * (0.9 + 0.7 * uA.y) * uM.z;

  // Núcleo de energía con corona que pulsa con cada golpe.
  float coreR = 0.06 + 0.012 * uA.y + 0.03 * kick;
  float corona = 0.5 + 0.5 * noise(vec2(atan(p.y, p.x) * 3.0, t * 2.0));
  col += mix(uC1, uC3, 0.6) * smoothstep(coreR, coreR * 0.6, r) * (1.4 + 1.6 * kick);
  col += uC1 * (0.002 + 0.006 * kick) / (r * r + 0.003) * (0.7 + 0.3 * corona);

  col += mix(uC1, uC3, 0.5) * uM.y * 0.15;
  col *= 1.0 - 0.3 * smoothstep(0.6, 1.4, length(p * vec2(0.9, 0.6)));
  col = clamp((col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14), 0.0, 1.0);
  col = pow(col, vec3(0.4545));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  struct Dot { float x, y, z, seed; int band, group; };
  std::vector<Dot> dots;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0, mids = 0;
  std::array<float, 31> spec{};
  // Fases en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double yaw = 0, tilt = 0, sinceBurst = 100;
  float explode = 0, explodeVel = 0, breath = 0, breathVel = 0;
  float ringR = 3.0f, ringAmp = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static float hash(float n) {
    float x = std::sin(n) * 43758.5453f;
    return x - std::floor(x);
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    dots.clear();
    bass = body = spark = energy = slowBass = kick = flash = drive = mids = 0;
    spec.fill(0);
    yaw = rng.unit() * 6.2831853;
    tilt = rng.unit() * 6.2831853;
    sinceBurst = 100;
    explode = explodeVel = breath = breathVel = 0;
    ringR = 3.0f;
    ringAmp = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    if (dots.empty()) {
      int count = int(2000.0f + 1000.0f * std::clamp(f.detail, 0.25f, 2.0f));
      dots.resize(count);
      const float golden = 2.39996323f;
      for (int i = 0; i < count; i++) {
        float y = 1.0f - 2.0f * (float(i) + 0.5f) / float(count);
        float r = std::sqrt(std::max(0.0f, 1.0f - y * y));
        float phi = float(i) * golden;
        Dot& d = dots[i];
        d.x = std::cos(phi) * r;
        d.y = y;
        d.z = std::sin(phi) * r;
        d.seed = hash(float(i) * 12.9898f + 3.1f);
        // El ecuador responde a los graves y los polos a los agudos.
        d.band = std::clamp(int(std::fabs(y) * 22.0f + d.seed * 9.0f), 0, 30);
        d.group = d.band < 8 ? 0 : (d.band < 18 ? 1 : 2);
      }
    }
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    float mi = 0;
    for (int i = 9; i < 21; i++) mi = std::max(mi, m.smoothSpectrum[i]);
    mids = follow(mids, mi, 12.0f, 3.0f, dt);
    for (int i = 0; i < 31; i++) spec[i] = follow(spec[i], m.smoothSpectrum[i], 25.0f, 5.0f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    sinceBurst += f.delta;
    if (hit > kick + 0.2f) {
      breathVel += 1.6f * hit;
      ringR = 0.0f;
      ringAmp = hit;
      // Drop: golpe fuerte con la música lanzada -> la esfera explota.
      if (hit > 0.7f && drive > 0.4f && sinceBurst > 6.0) {
        explodeVel += 4.5f * hit;
        sinceBurst = 0;
      }
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    // Muelles amortiguados: la explosión vuelve despacio y la respiración rápido.
    explodeVel += (-explode * 6.0f - explodeVel * 2.6f) * dt;
    explode += explodeVel * dt;
    breathVel += (-breath * 40.0f - breathVel * 7.0f) * dt;
    breath += breathVel * dt;
    ringR += dt * (0.8f + 0.5f * drive);
    ringAmp *= std::exp(-dt * 2.2f);

    yaw += f.delta * f.speed * (0.25 + 0.7 * drive + 0.9 * std::max(0.0f, explode));
    tilt += f.delta * f.speed * 0.13;
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    float s = std::min(f.width, f.height);
    float cx = f.width * 0.5f, cy = f.height * 0.5f;
    float R = 0.34f * s;
    std::vector<float> u;
    u.reserve(20);
    u.insert(u.end(), {float(std::fmod(yaw, 1000.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {f.glow, ringR, ringAmp * amp, std::max(0.0f, explode)});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("sonic_core", {0, 0, f.width, f.height}, u);
    if (dots.empty()) return;

    float cyaw = float(std::cos(yaw)), syaw = float(std::sin(yaw));
    float pitch = 0.45f * float(std::sin(tilt));
    float cp = std::cos(pitch), sp = std::sin(pitch);
    float ex = std::max(-0.3f, explode);
    float wob = float(std::fmod(yaw * 3.0, 6.2831853));
    // Nueve grupos: tres profundidades por tres colores.
    std::array<std::vector<Vec2>, 9> bins;
    for (auto& b : bins) b.reserve(dots.size() / 4);
    for (const Dot& d : dots) {
      // Púas irregulares: cada punto responde con distinta fuerza a su banda.
      float spike = d.seed * d.seed;
      float v = spec[d.band] * (0.25f + 1.6f * spike);
      // Olas lentas que recorren la superficie aunque no haya música.
      float rad = 1.0f + 0.12f * breath + 0.42f * v * amp + 0.05f * std::sin(d.y * 7.0f + wob * 2.0f) +
                  0.025f * std::sin(d.seed * 40.0f + wob) +
                  ex * (0.35f + 1.6f * d.seed);
      // Giro alrededor del eje vertical y luego inclinación.
      float x = d.x * cyaw + d.z * syaw;
      float z = -d.x * syaw + d.z * cyaw;
      float y = d.y * cp - z * sp;
      z = d.y * sp + z * cp;
      // En la explosión la nube se retuerce alrededor del eje.
      float twist = ex * (d.seed - 0.5f) * 1.5f;
      float tx = x * std::cos(twist) - z * std::sin(twist);
      float tz = x * std::sin(twist) + z * std::cos(twist);
      float persp = 3.2f / (3.2f - tz * rad);
      float sx = cx + tx * rad * R * persp;
      float sy = cy + y * rad * R * persp;
      int depth = tz < -0.3f ? 0 : (tz < 0.35f ? 1 : 2);
      bins[depth * 3 + d.group].push_back({sx, sy});
    }
    float px = s / 400.0f;
    float gain = std::clamp((0.8f + 0.5f * bass + 0.5f * kick) * amp, 0.0f, 1.5f);
    const float sizes[3] = {1.0f, 1.5f, 2.1f};
    const float alphas[3] = {0.30f, 0.62f, 0.95f};
    for (int depth = 0; depth < 3; depth++) {
      for (int g = 0; g < 3; g++) {
        const auto& pts = bins[depth * 3 + g];
        if (pts.empty()) continue;
        const Color& col = f.colors[1 + g];
        Paint halo;
        halo.blend = Blend::plus;
        halo.color = {col.r, col.g, col.b, std::clamp(0.07f * alphas[depth] * gain * f.glow, 0.0f, 1.0f)};
        c.points(pts, sizes[depth] * 3.2f * px, halo);
        Paint core;
        core.blend = Blend::plus;
        core.color = {col.r, col.g, col.b, std::clamp(alphas[depth] * gain, 0.0f, 1.0f)};
        c.points(pts, (sizes[depth] + 0.4f * spark * amp) * px, core);
      }
    }
  }
};

shaderSources.sonic_core:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // fase de giro, graves, golpe, energía
uniform vec4 uB;   // glow, radio y fuerza del anillo, explosión
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  float r = length(p);
  float bass = uA.y;
  float kick = uA.z;

  vec3 col = uC0;
  // Núcleo de energía dentro de la esfera y halo que la envuelve.
  col += uC1 * (0.004 + 0.010 * bass + 0.02 * kick) / (r * r + 0.02) * uB.x;
  col += uC1 * exp(-(r - 0.31) * (r - 0.31) * 60.0) * (0.03 + 0.05 * bass) * uB.x;
  // Anillo del golpe y fogonazo de la explosión.
  float ring = 0.31 + uB.y * 0.6;
  col += mix(uC1, uC3, 0.3) * uB.z * exp(-(r - ring) * (r - ring) * 900.0) * 0.8;
  col += mix(uC2, uC3, 0.5) * uB.w * 0.06 * smoothstep(1.0, 0.0, r);

  col *= 1.0 - 0.5 * smoothstep(0.4, 1.2, length(p * vec2(0.9, 0.65)));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

