#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;     // tiempo, graves, golpe, energía
uniform vec4 uT0;    // focos de arriba: ángulo, apertura, potencia, giro del dibujo
uniform vec4 uT1;
uniform vec4 uT2;
uniform vec4 uT3;
uniform vec4 uT4;
uniform vec4 uT5;
