class Visual final : public Scene {
  struct Star { float x, y, z0, cycle; };
  std::vector<Star> stars;
  float travel = 0.0f;
  float smoothBass = 0.0f;
  float smoothEnergy = 0.0f;
 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    stars.clear(); stars.reserve(621);
    travel = 0.0f; smoothBass = 0.0f; smoothEnergy = 0.0f;
    for (int i = 0; i < 621; i++) {
      Star s;
      s.x = (rng.unit() - 0.5f) * 2.2f;
      s.y = (rng.unit() - 0.5f) * 2.2f;
      s.z0 = rng.unit() * 2.2f + 0.05f;
      s.cycle = 2.2f + 1.2f;
      stars.push_back(s);
    }
  }
  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));

    // En silencio reposa en un crucero estelar pausado (~0.10f).
    // Con música acelera hacia velocidad hiperlumínica con estelas largas.
    float audioDrive = 0.10f + smoothEnergy * 0.90f + smoothBass * 0.45f;
    if (f.reducedMotion) audioDrive *= 0.4f;
    travel += dt * f.speed * audioDrive * 1.6f;
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float cx = w * 0.5f, cy = h * 0.5f;
    float boost = std::clamp((0.7f + 0.5f * smoothEnergy + 0.4f * smoothBass) * f.intensity, 0.0f, 1.0f);
    Paint bg; bg.color = Color::argb(0xff02020c);
    c.rect({0, 0, w, h}, bg);
    Path lanes[3];
    std::vector<Vec2> heads[3];
    for (int i = 0; i < 3; i++) heads[i].reserve(240);
    for (size_t idx = 0; idx < stars.size(); idx++) {
      const Star& s = stars[idx];
      float z = std::fmod(s.z0 - travel, s.cycle);
      if (z < 0.04f) z += s.cycle;
      float x1 = cx + (s.x / z) * 0.75f;
      float y1 = cy + (s.y / z) * 0.75f;
      if (x1 < -80 || x1 > w + 80 || y1 < -80 || y1 > h + 80) continue;
      float tail = z + 0.04f + smoothEnergy * 0.10f;
      int lane = int(idx % 3);
      lanes[lane].moveTo(cx + (s.x / tail) * 0.75f, cy + (s.y / tail) * 0.75f);
      lanes[lane].lineTo(x1, y1);
      heads[lane].push_back({x1, y1});
    }
    for (int lane = 0; lane < 3; lane++) {
      Paint p; p.blend = Blend::plus;
      if (lane == 0) { p.color = {1, 1, 1, 0.9f * boost}; p.strokeWidth = 1.7f; }
      else if (lane == 1) { p.color = {0.749f, 0.894f, 1, 0.55f * boost}; p.strokeWidth = 1.1f; }
      else { p.color = {1, 0.839f, 0.941f, 0.55f * boost}; p.strokeWidth = 1.1f; }
      p.strokeCap = 1; p.strokeJoin = 1;
      c.path(lanes[lane], p);
      if (!heads[lane].empty()) {
        Paint hp; hp.blend = Blend::plus;
        hp.color = {1, 1, 1, 0.85f * boost};
        c.points(heads[lane], 0.85f, hp);
      }
    }
    Paint glow = Paint::radial({cx, cy}, std::min(w, h) * 0.45f,
      {{0.549f, 0.745f, 1, 0.28f * boost}, {0, 0, 0, 0}});
    glow.blend = Blend::plus;
    c.rect({0, 0, w, h}, glow);
  }
};

class Visual final : public Scene {
  struct Star { float x, y, z0, cycle; };
  std::vector<Star> stars;
  float travel = 0.0f;
  float smoothBass = 0.0f;
  float smoothEnergy = 0.0f;
 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    stars.clear(); stars.reserve(621);
    travel = 0.0f; smoothBass = 0.0f; smoothEnergy = 0.0f;
    for (int i = 0; i < 621; i++) {
      Star s;
      s.x = (rng.unit() - 0.5f) * 2.2f;
      s.y = (rng.unit() - 0.5f) * 2.2f;
      s.z0 = rng.unit() * 2.2f + 0.05f;
      s.cycle = 2.2f + 1.2f;
      stars.push_back(s);
    }
  }
  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));

    // En silencio reposa en un crucero estelar pausado (~0.10f).
    // Con música acelera hacia velocidad hiperlumínica con estelas largas.
    float audioDrive = 0.10f + smoothEnergy * 0.90f + smoothBass * 0.45f;
    if (f.reducedMotion) audioDrive *= 0.4f;
    travel += dt * f.speed * audioDrive * 1.6f;
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float cx = w * 0.5f, cy = h * 0.5f;
    float boost = std::clamp((0.7f + 0.5f * smoothEnergy + 0.4f * smoothBass) * f.intensity, 0.0f, 1.0f);
    Path lanes[3];
    std::vector<Vec2> heads[3];
    for (int i = 0; i < 3; i++) heads[i].reserve(240);
    for (size_t idx = 0; idx < stars.size(); idx++) {
      const Star& s = stars[idx];
      float z = std::fmod(s.z0 - travel, s.cycle);
      if (z < 0.04f) z += s.cycle;
      float x1 = cx + (s.x / z) * 0.75f;
      float y1 = cy + (s.y / z) * 0.75f;
      if (x1 < -80 || x1 > w + 80 || y1 < -80 || y1 > h + 80) continue;
      float tail = z + 0.04f + smoothEnergy * 0.10f;
      int lane = int(idx % 3);
      lanes[lane].moveTo(cx + (s.x / tail) * 0.75f, cy + (s.y / tail) * 0.75f);
      lanes[lane].lineTo(x1, y1);
      heads[lane].push_back({x1, y1});
    }
    for (int lane = 0; lane < 3; lane++) {
      Paint p; p.blend = Blend::plus;
      if (lane == 0) { p.color = {1, 1, 1, 0.9f * boost}; p.strokeWidth = 1.7f; }
      else if (lane == 1) { p.color = {0.749f, 0.894f, 1, 0.55f * boost}; p.strokeWidth = 1.1f; }
      else { p.color = {1, 0.839f, 0.941f, 0.55f * boost}; p.strokeWidth = 1.1f; }
      p.strokeCap = 1; p.strokeJoin = 1;
      c.path(lanes[lane], p);
      if (!heads[lane].empty()) {
        Paint hp; hp.blend = Blend::plus;
        hp.color = {1, 1, 1, 0.85f * boost};
        c.points(heads[lane], 0.85f, hp);
      }
    }
    Paint glow = Paint::radial({cx, cy}, std::min(w, h) * 0.45f,
      {{0.549f, 0.745f, 1, 0.28f * boost}, {0, 0, 0, 0}}, {0.0f, 1.0f});
    glow.blend = Blend::plus;
    c.circle({cx, cy}, std::min(w, h) * 0.45f, glow);
  }
};

class Visual final : public Scene {
  struct Part { float r, a0, spd, w; };
  struct Star { float x, y, m; };
  std::vector<Part> parts;
  std::vector<Star> stars;
  float horizonTime = 0.0f;
  float smoothEnergy = 0.0f;
  float smoothBass = 0.0f;
 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    parts.clear(); stars.clear();
    horizonTime = 0.0f; smoothEnergy = 0.0f; smoothBass = 0.0f;
    int np = 620;
    parts.reserve(np);
    for (int i = 0; i < np; i++) {
      Part p;
      float u = rng.unit();
      p.r = 1.55f + std::pow(u, 0.62f) * 3.6f;
      p.a0 = rng.unit() * 6.2831853f;
      // Kepler: la velocidad angular cae con r^1.5 => rotación diferencial real.
      p.spd = 1.0f / (p.r * std::sqrt(p.r));
      p.w = 0.5f + rng.unit() * 2.2f;
      parts.push_back(p);
    }
    stars.reserve(320);
    for (int i = 0; i < 320; i++) {
      Star s; s.x = rng.unit(); s.y = rng.unit(); s.m = rng.unit();
      stars.push_back(s);
    }
  }
  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));

    // En silencio reposa en una rotación gravitatoria lenta (~0.10f).
    // Con música acelera la rotación del disco y la deflexión relativista.
    float audioDrive = 0.10f + smoothEnergy * 0.75f + smoothBass * 0.35f;
    horizonTime += dt * f.speed * audioDrive;
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float t = horizonTime;
    float cx = w * 0.5f, cy = h * 0.5f;
    float rs = std::min(w, h) * 0.13f;
    float yaw = std::sin(t * 0.09f) * 0.22f * (1.0f + smoothEnergy * 0.3f);
    float squash = 0.24f + std::cos(t * 0.07f) * 0.14f;
    float boost = std::clamp((0.85f + 0.35f * smoothEnergy + 0.30f * smoothBass) * f.intensity, 0.0f, 1.0f);
    float spin = t * 0.06f * (f.reducedMotion ? 0.3f : 1.0f);
    Paint bg; bg.color = Color::argb(0xff030308);
    c.rect({0, 0, w, h}, bg);

    // ── Estrellas con deflexión gravitatoria ──
    std::vector<Vec2> field;
    field.reserve(stars.size());
    for (const auto& s : stars) {
      float bx = s.x * w, by = s.y * h;
      float dx = bx - cx, dy = by - cy;
      float d = std::sqrt(dx * dx + dy * dy) + 1.0f;
      if (d < rs * 1.25f) continue; // devoradas por la sombra
      float k = 1.0f + (rs * rs * 5.2f) / (d * d);
      field.push_back({cx + dx * k, cy + dy * k});
    }
    Paint sp; sp.blend = Blend::plus;
    sp.color = {0.863f, 0.910f, 1, 0.69f * boost};
    c.points(field, 1.1f, sp);

    const uint32_t ramp[4] = {0xffc9432a, 0xffff8f4a, 0xffffd166, 0xfffff3d0};

    // Disco: cuatro bandas de calor, dos pasadas para el orden.
    for (int pass = 0; pass < 2; pass++) {
      for (int b = 0; b < 4; b++) {
        Path disk;
        for (const auto& p : parts) {
          float heat = 1.0f - (p.r - 1.55f) / 3.6f;
          if (heat < 0.0f) heat = 0.0f; if (heat > 1.0f) heat = 1.0f;
          if (int(heat * 3.999f) != b) continue;
          float rad = p.r * rs;
          float a = p.a0 + spin * p.spd + yaw;
          float sa = std::sin(a);
          if ((sa < 0.0f ? 0 : 1) != pass) continue;
          float x = cx + std::cos(a) * rad;
          float y = cy + sa * rad * squash;
          float len = p.w * (2.2f + heat * 6.0f);
          disk.moveTo(x + std::sin(a) * len, y - std::cos(a) * squash * len);
          disk.lineTo(x, y);
        }
        Color cc = Color::argb(ramp[b]);
        Paint dp; dp.blend = Blend::plus;
        dp.color = {cc.r, cc.g, cc.b, (0.10f + float(b) * 0.14f) * boost};
        dp.strokeWidth = 0.7f + float(b) * 0.5f;
        dp.strokeCap = 1; dp.strokeJoin = 1;
        c.path(disk, dp);
      }
      if (pass == 0) {
        // ── Anillo fotónico ──
        float ringR = rs * 1.34f;
        Paint rp; rp.blend = Blend::plus;
        for (int i = 3; i >= 1; i--) {
          rp.color = {1, 0.819f, 0.400f, 0.051f * boost};
          rp.strokeWidth = rs * 0.16f * float(i);
          c.circle({cx, cy}, ringR * (1.0f + float(i) * 0.07f), rp);
        }
        Paint crisp; crisp.blend = Blend::plus;
        crisp.color = {1, 0.941f, 0.824f, 0.949f * boost};
        crisp.strokeWidth = std::max(1.0f, rs * 0.045f);
        c.circle({cx, cy}, ringR, crisp);
        // ── Sombra del horizonte ──
        Paint shadow; shadow.color = {0, 0, 0, 1};
        c.circle({cx, cy}, rs, shadow);
      }
    }

    // ── Arco de Einstein: imagen lensada del disco sobre el horizonte ──
    Path arc;
    const int steps = 48;
    for (int i = 0; i <= steps; i++) {
      float a = 3.14159265f * 1.06f + float(i) / float(steps) * 3.14159265f * 0.88f;
      float x = cx + std::cos(a) * rs * 1.16f;
      float y = cy + std::sin(a) * rs * 1.16f;
      if (i == 0) arc.moveTo(x, y); else arc.lineTo(x, y);
    }
    Paint ap; ap.blend = Blend::plus;
    ap.color = {1, 0.722f, 0.361f, 0.502f * boost};
    ap.strokeWidth = rs * 0.2f; ap.strokeCap = 1; ap.strokeJoin = 1;
    c.path(arc, ap);

    // Resplandor global.
    Paint glow = Paint::radial({cx, cy}, rs * 6.5f,
      {{1, 0.667f, 0.314f, 0.141f * boost}, {0.627f, 0.314f, 1, 0.051f * boost}, {0, 0, 0, 0}},
      {0.0f, 0.4f, 1.0f});
    glow.blend = Blend::plus;
    c.rect({0, 0, w, h}, glow);
  }
};

class Visual final : public Scene {
  std::vector<float> ridge;
  float synthTime = 0.0f;
  float smoothBass = 0.0f;
  float smoothEnergy = 0.0f;
  float pulse = 0;
  static float vhash(int x, int y) {
    uint32_t h = uint32_t(x) * 374761393u + uint32_t(y) * 668265263u;
    h = (h ^ (h >> 13)) * 1274126177u; h ^= h >> 16;
    return float(h & 0xffffu) / 65535.0f;
  }
  static float vnoise(float x, float y) {
    int xi = int(std::floor(x)), yi = int(std::floor(y));
    float xf = x - float(xi), yf = y - float(yi);
    float u = xf * xf * (3.0f - 2.0f * xf), v = yf * yf * (3.0f - 2.0f * yf);
    float a = vhash(xi, yi), b = vhash(xi + 1, yi);
    float c = vhash(xi, yi + 1), d = vhash(xi + 1, yi + 1);
    return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
  }
 public:
  Visual() {
    reset(0);
  }
  void reset(uint32_t seed) override {
    (void)seed;
    synthTime = 0.0f;
    smoothBass = 0.0f;
    smoothEnergy = 0.0f;
    pulse = 0;
    ridge.resize(30);
    for (int i = 0; i < 30; i++)
      ridge[i] = (vnoise(float(i) * 0.4f, 1.0f) * 0.5f + vnoise(float(i) * 0.9f, 7.0f) * 0.5f);
  }
  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));

    // En silencio reposa en un rodaje synthwave suave y relajante (~0.10f).
    // Con música acelera la perspectiva de la rejilla y los destellos del sol.
    float audioDrive = 0.10f + smoothEnergy * 0.78f + smoothBass * 0.35f;
    synthTime += dt * f.speed * audioDrive;

    if (ridge.size() != 30) {
      reset(0);
    }
    if (f.music.active) {
      for (const auto& band : f.music.events)
        for (const auto& e : band) pulse += e.strength;
    }
    pulse *= float(std::exp(-dt * 4.0));
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float t = synthTime;
    float hz = h * 0.56f;
    float glowBoost = std::clamp((0.7f + 0.6f * smoothBass + 0.8f * pulse) * f.intensity, 0.0f, 1.0f);
    Paint sky = Paint::linear({0, 0}, {0, hz},
      {Color::argb(0xff160034), Color::argb(0xff4a0a6b), Color::argb(0xffff4d78)}, {0, 0.55f, 1.0f});
    c.rect({0, 0, w, hz}, sky);
    float sr = std::min(w, h) * 0.22f;
    float sunCx = w * 0.5f, sunCy = hz - sr * 0.15f;
    c.save();
    Path sunClip; sunClip.circle({sunCx, sunCy}, sr);
    c.clip(sunClip);
    Paint sun = Paint::linear({0, hz - sr * 1.3f}, {0, hz + 4.0f},
      {Color::argb(0xfffff36b), Color::argb(0xffff8a3d), Color::argb(0xffff2e9a)}, {0, 0.45f, 1.0f});
    c.rect({sunCx - sr, hz - sr * 1.3f, sr * 2.0f, sr * 2.0f}, sun);
    Paint bar; bar.color = Color::argb(0xff160034);
    float lane = sr * 0.14f;
    float off = std::fmod(t * 14.0f, lane);
    for (int i = 0; i < 9; i++) {
      float y = hz - sr * 0.9f + float(i) * lane + off;
      c.rect({sunCx - sr, y, sr * 2.0f, float(i) * 0.55f + 1.5f}, bar);
    }
    c.restore();
    Path mtn; mtn.moveTo(0, hz);
    if (ridge.size() == 30) {
      for (int i = 0; i < 30; i++)
        mtn.lineTo(float(i) / 29.0f * w, hz - ridge[i] * h * 0.16f);
    }
    mtn.lineTo(w, hz); mtn.close();
    Paint mfill; mfill.color = Color::argb(0xff0d0020);
    c.path(mtn, mfill);
    Paint mstroke; mstroke.color = {1, 0.435f, 0.847f, std::min(1.0f, 0.9f * f.intensity)};
    mstroke.strokeWidth = 1.0f;
    c.path(mtn, mstroke);
    Paint floor = Paint::linear({0, hz}, {0, h},
      {Color::argb(0xff12002b), Color::argb(0xff2a004d)});
    c.rect({0, hz, w, h - hz}, floor);
    Path grid;
    for (int i = -9; i <= 9; i++) {
      grid.moveTo(w * 0.5f, hz);
      grid.lineTo(w * 0.5f + float(i) * w * 0.34f, h);
    }
    float speed = std::fmod(t * 0.55f, 1.0f);
    for (int i = 0; i < 16; i++) {
      float k = (float(i) + speed) / 16.0f;
      float y = hz + (h - hz) * k * k * 1.02f;
      if (y > h) continue;
      grid.moveTo(0, y); grid.lineTo(w, y);
    }
    Paint gp; gp.color = {0, 1, 0.965f, std::min(1.0f, 0.75f * f.intensity)};
    gp.strokeWidth = 1.1f;
    c.path(grid, gp);
    Paint hg = Paint::linear({0, hz - 26.0f}, {0, hz + 26.0f},
      {{1, 0.18f, 0.604f, 0}, {1, 0.47f, 0.784f, 0.35f * glowBoost}, {0, 1, 0.965f, 0}}, {0, 0.5f, 1.0f});
    hg.blend = Blend::plus;
    c.rect({0, hz - 26.0f, w, 52.0f}, hg);
  }
};

class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  double phase = 0, drift = 0, sinceMorph = 0;
  std::array<float, 4> from{}, to{};
  float morph = 1, breath = 0, breathVel = 0;
  int beats = 0, shape = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  // Formas elegidas: giro inicial, giro por iteración, frecuencia y remolino.
  static std::array<float, 4> shapeAt(int i) {
    static const float shapes[6][4] = {{0.8f, 1.3f, 1.3f, 1.0f}, {0.6f, 1.7f, 1.1f, 1.8f}, {1.5f, 1.1f, 1.2f, 1.3f},
                                       {0.9f, 2.4f, 1.4f, 0.9f}, {0.1f, 2.0f, 1.5f, 1.4f}, {0.3f, 0.9f, 1.7f, 0.6f}};
    const float* s = shapes[((i % 6) + 6) % 6];
    return {s[0], s[1], s[2], s[3]};
  }

  void next() {
    float e = morph * morph * (3.0f - 2.0f * morph);
    for (int i = 0; i < 4; i++) from[i] = from[i] + (to[i] - from[i]) * e;
    shape++;
    to = shapeAt(shape);
    morph = 0;
    sinceMorph = 0;
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    phase = rng.unit() * 6.2831853;
    drift = rng.unit() * 10.0;
    sinceMorph = 0;
    shape = int(rng.unit() * 6.0f);
    from = to = shapeAt(shape);
    morph = 1;
    breath = breathVel = 0;
    beats = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      beats++;
      breathVel += 1.4f * hit;
      if (beats % 2 == 0) next();
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    // La llama respira con el golpe y vuelve con un muelle amortiguado.
    breathVel += (-breath * 30.0f - breathVel * 6.0f) * dt;
    breath += breathVel * dt;
    morph = std::min(1.0f, morph + dt * 1.1f);
    sinceMorph += f.delta;
    // En silencio la llama cambia de forma cada diez segundos.
    if (!m.active && sinceMorph > 10.0) next();
    phase += f.delta * f.speed * (0.07 + 0.25 * drive + 0.1 * bass);
    drift += f.delta * f.speed * (0.15 + 0.3 * drive);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    float e = morph * morph * (3.0f - 2.0f * morph);
    std::array<float, 4> p;
    for (int i = 0; i < 4; i++) p[i] = from[i] + (to[i] - from[i]) * e;
    // Ondulación lenta del remolino para que la seda nunca quede quieta.
    p[3] += 0.15f * float(std::sin(drift * 0.9));
    p[2] += 0.05f * float(std::sin(drift * 0.6 + 1.3));
    std::vector<float> u;
    u.reserve(24);
    u.insert(u.end(), {float(std::fmod(phase, 6.2831853)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {p[0], p[1], p[2], p[3]});
    u.insert(u.end(), {f.glow, spark * amp, 1.0f + 0.08f * breath * amp, flash * amp});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("flame", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.flame:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // fase de giro, graves, golpe, energía
uniform vec4 uP;   // giro inicial, giro por iteración, frecuencia, remolino
uniform vec4 uD;   // glow, agudos, zoom, destello
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// Paleta en luz lineal por iteración: azul, violeta y blanco lavanda.
vec3 palette(float x) {
  vec3 c1 = pow(uC1, vec3(2.2));
  vec3 c2 = pow(uC2, vec3(2.2));
  vec3 c3 = pow(uC3, vec3(2.2));
  return x < 0.5 ? mix(c1, c2, x * 2.0) : mix(c2, c3, x * 2.0 - 1.0);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  vec2 z = p * 2.2 / uD.z;
  float kick = uA.z;

  vec3 glow = vec3(0.0);
  for (int i = 0; i < 5; i++) {
    float fi = float(i);
    float ang = uP.x + fi * uP.y + uA.x;
    float ca = cos(ang);
    float sa = sin(ang);
    z = vec2(ca * z.x - sa * z.y, sa * z.x + ca * z.y);
    // Variación sinusoidal seguida de un remolino.
    z = sin(z * uP.z) * 1.3;
    float r2 = dot(z, z);
    float cs = cos(r2 * uP.w);
    float ss = sin(r2 * uP.w);
    z = vec2(z.x * ss - z.y * cs, z.x * cs + z.y * ss);
    // La órbita brilla cerca de una línea y de un anillo: cintas de seda.
    float k = 14.0 * (1.0 + 0.35 * fi);
    float trap = exp(-abs(z.y) * k) + 0.4 * exp(-abs(length(z) - 0.8) * k);
    float weight = 1.0 / (1.0 + 0.55 * fi);
    if (i == 4) weight *= 1.0 + 2.0 * uD.y;
    glow += palette(fi * 0.25) * trap * weight;
  }

  float r = length(p);
  float gain = (1.3 + 0.8 * uA.y + 1.1 * kick + 0.3 * uA.w) * uD.x;
  vec3 I = glow * (0.25 + 1.2 * exp(-r * r * 3.0));
