  vec3 col = uC0;
  float spot = exp(-(p.x * p.x * 2.5 + (p.y + 0.9) * (p.y + 0.9) * 1.2));
  col += uC1 * spot * (0.10 + 0.08 * uA.y + 0.12 * uA.z) * uB.x;
  float floorGlow = exp(-(p.x * p.x * 1.5 + (p.y - 0.75) * (p.y - 0.75) * 6.0));
