  float scale = min(uSize.x, uSize.y);
  // Retícula de rombos: escamas colgadas de su esquina superior en filas
  // alternas, como las lentejuelas de una fachada cinética.
  float pitch = scale / (12.0 + 5.0 * uD.z);
  vec2 rot = vec2(frag.x + frag.y, frag.y - frag.x) * 0.70710678 / pitch;
  vec2 cellR = floor(rot);
  vec2 centerR = cellR + 0.5;
  vec2 c = vec2(centerR.x - centerR.y, centerR.x + centerR.y) * 0.70710678 * pitch;
  float R = pitch * 0.70710678;
  vec2 d = frag - c;
  vec2 q = c / scale;
  float t = uA.x;

  // Inclinación de cada escama: olas de viento que viajan, ráfaga del golpe
  // y un aleteo propio.
  float w = noise(q * vec2(2.2, 1.4) + vec2(-t * 0.7, t * 0.18)) - 0.5;
  w += 0.5 * (noise(q * 5.0 + vec2(t * 1.3, -t * 0.4)) - 0.5);
  float h = hash12(cellR);
  float flutter = (h - 0.5) * 0.25 * sin(uD.w * (5.0 + 4.0 * h) + h * 40.0);
  float gust = uB.y * exp(-(q.x - uB.x) * (q.x - uB.x) * 14.0) * (0.8 + 0.4 * noise(q * 3.0 + t));
  float tilt = w * (1.1 + 0.9 * uA.y) + gust * 1.2 + flutter * (1.0 + uA.y);

  // La escama cuelga de su esquina superior: al inclinarse se ve más corta.
  float ct = max(abs(cos(tilt)), 0.06);
  float yp = (d.y + R) / ct - R;
  float shape = abs(d.x) + abs(yp);
  float inside = 1.0 - smoothstep(R * 0.84, R * 0.9, shape);
  // Reflejo: la escama es levemente curva y la luz se desliza por ella.
  float ry = sin(2.0 * tilt) + (yp / R) * 0.15;
  float band = exp(-(ry - 0.3) * (ry - 0.3) * 16.0);
  float sunHit = exp(-(ry - uB.z) * (ry - uB.z) * 45.0);
  float env = smoothstep(-1.0, 1.0, -ry);
  vec3 plate = uC2 * (0.06 + 0.16 * env) * (0.85 + 0.3 * h);
  plate += uC1 * band * (0.35 + 0.35 * uA.y + 0.5 * uA.z) * uB.w;
  plate += uC3 * sunHit * (0.85 + 1.0 * uA.z + 0.6 * uD.x);
  // Bisel: el canto de la escama atrapa algo más de luz.
  float rim = smoothstep(R * 0.68, R * 0.86, shape);
  plate += uC2 * rim * (0.08 + 0.25 * sunHit + 0.15 * band);
  // Destellos sueltos con los agudos y fogonazo del destello sobre el metal.
  float tw = step(0.992 - 0.012 * uD.x, hash12(cellR + floor(uD.w * 7.0)));
  plate += uC3 * tw * uD.x * 0.9;
  plate += uC2 * uD.y * 0.25;
  // Pared oscura con la sombra de la escama debajo.
  float shadow = 1.0 - 0.5 * smoothstep(R * 1.1, R * 0.6, abs(d.x) + abs(yp - R * 0.18));
  vec3 col = uC0 * 0.7 * shadow;
  col = mix(col, plate, inside);
  col *= 1.0 - 0.35 * smoothstep(0.6, 1.4, length((frag - 0.5 * uSize) / scale * vec2(0.9, 0.65)));
  // Fondo transparente: color premultiplicado y opacidad según el brillo; la
  // luz muy tenue se vuelve transparente del todo para no dejar velo.
  col = clamp(col, 0.0, 1.0);
  float veilPeak = max(col.r, max(col.g, col.b));
  float clearCut = smoothstep(0.04, 0.12, veilPeak);
  col *= clearCut;
  float alpha = clamp(veilPeak * 1.25, 0.0, 1.0) * clearCut;
  fragColor = vec4(col, alpha);
}

visuals.nativeSource:
class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0, warm = 0, cool = 0;
  float phase = 0, drift = 0, push = 0;
  std::array<float, 4> shocks{};  // radio, amplitud, radio, amplitud

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = warm = cool = 0;
    phase = rng.unit() * 30.0f;
    drift = rng.unit() * 20.0f;
    push = 0;
    shocks = {6.0f, 0.0f, 6.0f, 0.0f};
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 20.0f, 4.0f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);
    float low = 0, high = 0;
    for (int i = 0; i < 10; i++) low = std::max(low, m.smoothSpectrum[i]);
    for (int i = 18; i < 31; i++) high = std::max(high, m.smoothSpectrum[i]);
    warm = follow(warm, low, 10.0f, 2.5f, dt);
    cool = follow(cool, high, 10.0f, 2.5f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      shocks[2] = shocks[0];
      shocks[3] = shocks[1];
      shocks[0] = 0.0f;
      shocks[1] = hit;
    }
    kick = std::max(kick * std::exp(-dt * 4.5f), hit);
    flash = std::max(flash * std::exp(-dt * 7.0f), std::min(fl, 1.0f));
    for (int i = 0; i < 4; i += 2) {
      shocks[i] += dt * 0.85f;
      shocks[i + 1] *= std::exp(-dt * 1.3f);
    }

    phase += dt * f.speed * (0.10f + 0.6f * drive + 0.5f * kick);
    drift += dt * f.speed * (0.02f + 0.08f * drive);
    push = follow(push, kick, 12.0f, 2.5f, dt);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(32);
    u.insert(u.end(), {phase, bass * amp, kick * amp, energy});
    u.insert(u.end(), {shocks[0], shocks[1] * amp, shocks[2], shocks[3] * amp});
    u.insert(u.end(), {warm, cool, spark * amp, f.glow});
    u.insert(u.end(), {drift, push * amp, flash, f.detail});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("nebula", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.nebula:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // tiempo, graves, golpe, energía
uniform vec4 uS;   // ondas de choque: radio, amplitud, radio, amplitud
uniform vec4 uT;   // cálido, frío, agudos, glow
uniform vec4 uX;   // deriva, empuje, destello, detalle
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

// Campana gaussiana segura: pow() con base negativa no está definido en GLSL.
float gauss(float x) {
  return exp(-x * x);
}

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

float fbm(vec2 p) {
  float s = 0.0;
  float a = 0.5;
  for (int i = 0; i < 5; i++) {
    s += a * noise(p);
    p = mat2(1.6, 1.2, -1.2, 1.6) * p + vec2(1.3, -0.7);
    a *= 0.5;
  }
  return s;
}

float fbmLow(vec2 p) {
  float s = 0.0;
  float a = 0.5;
  for (int i = 0; i < 3; i++) {
    s += a * noise(p);
    p = mat2(1.6, 1.2, -1.2, 1.6) * p + vec2(1.3, -0.7);
    a *= 0.5;
  }
  return s / 0.875 * 0.97;
}

// Ruido de crestas: filamentos finos y brillantes.
float ridged(vec2 p) {
  float s = 0.0;
  float a = 0.55;
  for (int i = 0; i < 4; i++) {
    float n = 1.0 - abs(noise(p) * 2.0 - 1.0);
    s += a * n * n;
    p = mat2(1.7, 1.1, -1.1, 1.7) * p + vec2(-2.1, 0.4);
    a *= 0.5;
  }
  return s;
}

float stars(vec2 uv, float scale, float threshold) {
  vec2 g = uv * scale;
  vec2 id = floor(g);
  vec2 f = fract(g) - 0.5;
  float h = hash12(id);
  vec2 o = vec2(hash12(id + 3.1), hash12(id + 7.7)) - 0.5;
  float d = length(f - o * 0.7);
  float tw = 0.55 + 0.45 * sin(uA.x * (3.0 + 6.0 * uT.z) + h * 40.0);
  return smoothstep(0.09, 0.0, d) * step(threshold, h) * tw;
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 uv = (frag - 0.5 * uSize) / scale;
  uv.y = -uv.y;
  float t = uA.x;
  float kick = uA.z;

  // Empuje de cámara con el golpe y onda de choque que curva la luz.
  uv /= 1.0 + 0.10 * uX.y;
  vec2 core = vec2(0.06, 0.04);
  vec2 rel = uv - core;
  float r = length(rel);
  float shock = uS.y * gauss((r - uS.x) * 9.0) + uS.w * gauss((r - uS.z) * 9.0);
  vec2 lens = rel / max(r, 0.001) * shock * 0.035;
  vec2 p = uv + lens;

  vec2 drift = vec2(uX.x * 0.6, uX.x * 0.25);
  vec2 q = p * 1.35 + drift;
  vec2 w = vec2(fbmLow(q + vec2(0.0, t * 0.04)), fbmLow(q + vec2(5.2, -t * 0.03)));
  w = (w - 0.5) * (1.4 + 0.45 * uA.y);
  float gas = fbm(q * 1.1 + w);
  float fil = ridged(q * 1.9 + w * 1.6 + vec2(t * 0.02, 0.0));
  float dust = smoothstep(0.50, 0.72, fbmLow(q * 1.6 + w * 0.8 + vec2(11.0, 3.0)));
  vec2 nearQ = p * 2.6 + drift * 1.8 + w * 0.5;
  float wisps = fbmLow(nearQ + vec2(t * 0.05, 0.0));

  // Color de emisión: dos gases que se mezclan, desplazados por el espectro.
  float mixer = smoothstep(0.25, 0.75, w.x * 0.5 + 0.5 + 0.35 * (uT.y - uT.x));
  vec3 emit = mix(uC1, uC2, mixer);
  float coreLight = (0.08 + 0.18 * uA.y + 0.9 * kick) / (0.015 + r * r * 5.0);
  float density = pow(clamp(gas * 1.35 - 0.25, 0.0, 1.0), 2.2);
  vec3 neb = emit * density * (0.45 + 0.22 * uA.y + 0.1 * uA.w);
  neb += mix(emit, uC3, 0.2) * pow(fil, 3.0) * density * (0.6 + 0.7 * uT.z + 0.15 * uA.y);
  neb *= 1.0 + coreLight * 0.25;
  neb += mix(emit, uC3, 0.5) * shock * density * 1.8;
  neb += uC2 * pow(clamp(wisps * 1.4 - 0.45, 0.0, 1.0), 2.0) * (0.12 + 0.25 * uA.y);

  vec3 col = uC0;
  float st = stars(p + drift * 0.2, 80.0, 0.975) + stars(p + drift * 0.5 + 7.0, 34.0, 0.988) * 1.6;
  col += vec3(0.9, 0.93, 1.0) * st * (1.0 - dust * 0.9) * (0.7 + 0.8 * uT.z);
  col += neb * (1.0 - 0.85 * dust) * uT.w;
  // Estrella joven en el núcleo con destello en cruz.
  float star = (0.0022 + 0.008 * kick + 0.002 * uA.y) / (r * r + 0.0008);
  float spikes = (0.0006 + 0.004 * kick) / (abs(rel.x * rel.y) * 30.0 + 0.0006) * exp(-r * 6.0);
  col += uC3 * (star + spikes) * (1.0 - 0.5 * dust);
  col += mix(uC2, uC3, 0.5) * uX.z * 0.08;

  col *= 1.0 - 0.4 * smoothstep(0.45, 1.25, length(uv * vec2(0.9, 0.7)));
  // Realce de croma: el gas conserva su color en los momentos intensos.
  float luma = dot(col, vec3(0.299, 0.587, 0.114));
  col = max(mix(vec3(luma), col, 1.35), 0.0);
  col = clamp((col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14), 0.0, 1.0);
  col = pow(col, vec3(0.4545));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  struct Bld { float x, w, h; };
  struct Win { float x, y; };
  struct Layer { std::vector<Bld> blds; std::vector<Win> wins;
                 float speed, shade, depth, height; };
  std::vector<Layer> layers;
  struct Drop { float x, y, v, len; };
  std::vector<Drop> drops;
  float lastw = 0, lasth = 0, lastDetail = -1.0f;
  static float hash01(int i, int salt) {
    float s = std::sin(float(i) * 12.9898f + float(salt) * 78.233f) * 43758.5453f;
    return s - std::floor(s);
  }
  void build(float w, float h, float detail) {
    float horizon = h * 0.66f;
    layers.clear();
    for (int li = 0; li < 4; li++) {
      Layer L;
      L.depth = float(li) / 3.0f;
      L.speed = 3.0f + L.depth * 22.0f;
      int sh = 10 + int((1.0f - L.depth) * 22.0f);
      L.shade = float(sh);
      L.height = horizon * (0.32f + L.depth * 0.66f);
      int steps = int(w / 30.0f) + 6;
      if (steps > 48) steps = 48;
      // El paso de la ventana escala con la altura de la capa: en pantallas
      // grandes el número de puntos se disparaba y reventaba el presupuesto
      // de 1 MiB de comandos del motor.
      float wyStep = std::max(9.0f, L.height / 40.0f);
      // El paso horizontal sigue a la pantalla para que el skyline siempre la
      // cubra entera, tenga el ancho que tenga.
      float xStep = w / float(steps);
      for (int i = 0; i < steps; i++) {
        Bld b;
        b.x = (float(i) + hash01(i, li) * 0.6f) * xStep;
        b.w = xStep * (0.5f + hash01(i, li + 91) * 1.5f) * (0.5f + L.depth * 0.5f);
        b.h = L.height * (0.28f + hash01(i, li + 173) * 0.72f);
        L.blds.push_back(b);
        if (L.depth > 0.35f) {
          float top = L.height - b.h;
          float wxStep = std::max(7.0f, b.w / 8.0f);
          for (float wy = 6.0f; wy < b.h - 8.0f; wy += wyStep) {
            for (float wx = 3.0f; wx < b.w - 6.0f; wx += wxStep) {
              if (hash01(int(wx) * 7 + int(wy) * 13, li + 311) > 0.62f)
                L.wins.push_back({b.x + wx, top + wy});
            }
          }
        }
      }
      layers.push_back(L);
    }
    int ndrops = int(380.0f * std::min(1.0f, std::max(0.4f, detail)));
    drops.clear(); drops.reserve(ndrops);
    for (int i = 0; i < ndrops; i++)
      drops.push_back({hash01(i, 7) * w, hash01(i, 29) * h,
        520.0f + hash01(i, 53) * 620.0f, 8.0f + hash01(i, 71) * 26.0f});
  }
  float rainTime = 0.0f;
  float smoothEnergy = 0.0f;
  float smoothBass = 0.0f;
 public:
  void reset(uint32_t seed) override {
    (void)seed;
    layers.clear(); drops.clear();
    rainTime = 0.0f; smoothEnergy = 0.0f; smoothBass = 0.0f;
    lastw = 0; lasth = 0; lastDetail = -1.0f;
  }
  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));

    // En silencio reposa en una llovizna urbana tranquila (~0.12f).
    // Con música la lluvia y la ciudad cobran dinamismo y resplandor.
    float audioDrive = 0.12f + smoothEnergy * 0.76f + smoothBass * 0.35f;
    rainTime += dt * f.speed * audioDrive;

    if (f.width != lastw || f.height != lasth || f.detail != lastDetail) {
      build(f.width, f.height, f.detail);
      lastw = f.width; lasth = f.height; lastDetail = f.detail;
    }
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float t = rainTime;
    float horizon = h * 0.66f;
    float boost = std::clamp((0.85f + 0.35f * smoothEnergy) * f.intensity, 0.0f, 1.0f);
    Paint sky = Paint::linear({0, 0}, {0, h},
      {Color::argb(0xff05060c), Color::argb(0xff131a2c), Color::argb(0xff2a1c2c),
       Color::argb(0xff0a0c14), Color::argb(0xff04050a)}, {0, 0.42f, 0.63f, 0.67f, 1.0f});
    c.rect({0, 0, w, h}, sky);

    // Rótulos de neón con parpadeo eléctrico.
    const uint32_t neon[4] = {0xffff6a55, 0xff58c7f3, 0xff3fd8a5, 0xffffd166};
    Paint add; add.blend = Blend::plus;
    for (int i = 0; i < 7; i++) {
      float ph = float(i) * 1.7f;
      float flick = 0.55f + 0.45f * std::sin(t * 44.0f + ph) * std::sin(t * 14.0f + ph * 2.0f);
      if (flick < 0.06f) flick = 0.06f;
      if (flick > 1.0f) flick = 1.0f;
      Color cc = Color::argb(neon[i % 4]);
      add.color = {cc.r, cc.g, cc.b, flick * 0.85f * boost};
      int sw = int(w) - 90; if (sw < 1) sw = 1;
      int shh = int(horizon * 0.5f); if (shh < 1) shh = 1;
      float x = float((i * 137) % sw) + 30.0f;
      float y = horizon - 40.0f - float((i * 211) % shh);
      c.rect({x, y, 8.0f + float((i * 7) % 26), 18.0f + float((i * 13) % 54)}, add);
    }

    // 1. Ciudad en capas (sin clip innecesario).
    for (size_t li = 0; li < layers.size(); li++) {
      const Layer& L = layers[li];
      float period = std::max(w, 1.0f);
      float off = std::fmod(t * L.speed, period);
      float alpha = 0.35f + L.depth * 0.65f;
      for (int rep = 0; rep < 2; rep++) {
        float dx = -off + float(rep) * period;
        Path body;
        for (const auto& b : L.blds)
          body.rect({dx + b.x, L.height - b.h, b.w - 2.0f, b.h});
        Paint fill;
        fill.color = {L.shade / 255.0f, (L.shade + 3.0f) / 255.0f,
          (L.shade + 10.0f) / 255.0f, alpha};
        c.path(body, fill);
        if (!L.wins.empty()) {
          std::vector<Vec2> win;
          win.reserve(L.wins.size() * 2);
          for (const auto& p : L.wins) {
            win.push_back({dx + p.x, p.y});
            win.push_back({dx + p.x, p.y});
          }
          Paint wp; wp.blend = Blend::plus;
          wp.color = {1, 0.851f, 0.627f, 0.5f * alpha * boost};
          c.points(win, 1.7f, wp);
        }
      }
    }

    // 2. Reflejo mojado invertido (un solo clip para todas las capas combinadas).
    c.save();
    Path refClip;
    refClip.rect({0, horizon, w, h - horizon});
    c.clip(refClip);
    c.translate(0, horizon);
    c.scale(1, -0.42f);
    c.translate(0, -horizon);
    for (size_t li = 0; li < layers.size(); li++) {
      const Layer& L = layers[li];
      float period = std::max(w, 1.0f);
      float off = std::fmod(t * L.speed, period);
      float alpha = (0.35f + L.depth * 0.65f) * 0.2f;
      for (int rep = 0; rep < 2; rep++) {
        float dx = -off + float(rep) * period;
        Path body;
        for (const auto& b : L.blds)
          body.rect({dx + b.x, L.height - b.h, b.w - 2.0f, b.h});
        Paint fill;
        fill.color = {L.shade / 255.0f, (L.shade + 3.0f) / 255.0f,
          (L.shade + 10.0f) / 255.0f, alpha};
        c.path(body, fill);
        if (!L.wins.empty()) {
          std::vector<Vec2> win;
          win.reserve(L.wins.size() * 2);
          for (const auto& p : L.wins) {
            win.push_back({dx + p.x, p.y});
            win.push_back({dx + p.x, p.y});
          }
          Paint wp; wp.blend = Blend::plus;
          wp.color = {1, 0.851f, 0.627f, 0.1f * (0.35f + L.depth * 0.65f) * boost};
          c.points(win, 1.7f, wp);
        }
      }
    }
    c.restore();

    // Niebla en el horizonte.
    float fogTop = horizon - h * 0.18f;
    Paint fog = Paint::linear({0, fogTop}, {0, fogTop + h * 0.22f},
      {{0.47f, 0.314f, 0.408f, 0}, {0.588f, 0.373f, 0.471f, 0.6f * boost}});
    c.rect({0, fogTop, w, h * 0.22f}, fog);

    // Lluvia: un solo Path con un segmento por gota.
    Path rain;
    float wind = std::sin(t * 0.23f) * 40.0f;
    for (const auto& d : drops) {
      float y = std::fmod(d.y + t * d.v, h + 60.0f) - 20.0f;
      float x = std::fmod(d.x + wind * (y / h), w);
      if (x < 0) x += w;
      rain.moveTo(x, y);
      rain.lineTo(x - wind * 0.02f, y + d.len);
    }
    Paint rp; rp.blend = Blend::plus;
    rp.color = {0.745f, 0.843f, 1, 0.42f * boost};
    rp.strokeWidth = 1.0f; rp.strokeCap = 1; rp.strokeJoin = 1;
    c.path(rain, rp);
  }
};

class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Fase en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
  double phase = 0, swirl = 0;
  float ringR = 30.0f, ringAmp = 0;

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static Color shade(const Color& c, float g) {
    return {std::min(1.0f, c.r * g), std::min(1.0f, c.g * g), std::min(1.0f, c.b * g), 1.0f};
  }

  static Color blend(const Color& a, const Color& b, float t) {
    return {a.r + (b.r - a.r) * t, a.g + (b.g - a.g) * t, a.b + (b.b - a.b) * t, 1.0f};
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    phase = rng.unit() * 6.2831853;
    swirl = rng.unit() * 6.2831853;
    ringR = 30.0f;
    ringAmp = 0;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      ringR = 0.0f;
      ringAmp = hit;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
    ringR += dt * (9.0f + 4.0f * drive);
    ringAmp *= std::exp(-dt * 1.4f);
    phase += f.delta * f.speed * (1.4 + 2.2 * drive);
    swirl += f.delta * f.speed * 0.15;
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(20);
    u.insert(u.end(), {float(std::fmod(phase, 1000.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {f.glow, spark * amp, flash * amp, 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("cube_floor", {0, 0, f.width, f.height}, u);

    int n = int(15.0f + 4.0f * std::clamp(f.detail, 0.25f, 2.0f));
    float hw = f.width / (float(n) * 0.82f);  // medio ancho de una baldosa
    float hh = hw * 0.5f;
    float cx = f.width * 0.5f;
    float top = f.height * 0.5f - float(n) * hh + hw * 1.2f;
    float center = float(n - 1) * 0.5f;
    float t = float(std::fmod(phase, 6283.0));
    float baseH = hw * 1.2f;
    float waveH = hw * (1.6f + 1.4f * bass) * amp;
    const Color& coral = f.colors[1];
    const Color& ivory = f.colors[2];
    const Color& deep = f.colors[3];
    float glowKick = 1.0f + 0.35f * kick * amp + 0.25f * flash * amp;
    float sw = float(std::sin(swirl));
    // Pintor: diagonales de atrás hacia delante.
    for (int sum = 0; sum <= 2 * (n - 1); sum++) {
      for (int i = std::max(0, sum - (n - 1)); i <= std::min(n - 1, sum); i++) {
        int j = sum - i;
        float X = cx + float(i - j) * hw;
        float Y = top + float(i + j) * hh;
        float di = float(i) - center, dj = float(j) - center;
        float d = std::sqrt(di * di + dj * dj);
        float wave = 0.5f + 0.5f * std::sin(d * 0.55f - t + sw * 0.4f * di * 0.1f);
        float ring = ringAmp * std::exp(-(d - ringR) * (d - ringR) * 0.25f);
        float k = std::clamp(wave + 0.9f * ring * amp, 0.0f, 1.8f);
        float H = baseH + waveH * k;
        // Recorte: columnas fuera de la pantalla no se dibujan.
        if (X + hw < 0 || X - hw > f.width || Y - hh - H > f.height || Y + hh < 0) continue;
        float lift = std::clamp(k / 1.2f, 0.0f, 1.0f);
        Color topC = shade(blend(blend(coral, ivory, 0.8f), ivory, lift), (0.82f + 0.25f * lift) * glowKick);
        Color leftC = shade(blend(coral, deep, 0.15f - 0.15f * lift), (0.75f + 0.3f * lift) * glowKick);
        Color rightC = shade(blend(coral, deep, 0.55f), (0.6f + 0.2f * lift) * glowKick);
        Path left, right, cap;
        left.moveTo(X - hw, Y - H).lineTo(X, Y + hh - H).lineTo(X, Y + hh).lineTo(X - hw, Y).close();
        right.moveTo(X, Y + hh - H).lineTo(X + hw, Y - H).lineTo(X + hw, Y).lineTo(X, Y + hh).close();
        cap.moveTo(X, Y - hh - H).lineTo(X + hw, Y - H).lineTo(X, Y + hh - H).lineTo(X - hw, Y - H).close();
        Paint pl, pr, pt;
        pl.color = leftC;
        pr.color = rightC;
        pt.color = topC;
        c.path(left, pl);
        c.path(right, pr);
        c.path(cap, pt);
      }
    }
  }
};

