class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0, mids = 0, highs = 0;
  // Fase en doble precisión: la escena sin música es idéntica a 30 y 60 FPS.
