#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // reloj, graves, golpe, energía
uniform vec4 uB;   // patrón actual, patrón siguiente, fundido, destello
uniform vec4 uR;   // radio y fuerza del anillo del golpe, giro, alternancia
uniform vec4 uD;   // glow, agudos, medios, detalle
uniform vec4 uS0;  // espectro en 16 bandas
uniform vec4 uS1;
uniform vec4 uS2;
uniform vec4 uS3;
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

const float TAU = 6.2831853;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float band(float b) {
  vec4 s = b < 4.0 ? uS0 : (b < 8.0 ? uS1 : (b < 12.0 ? uS2 : uS3));
  float k = mod(b, 4.0);
  return k < 1.0 ? s.x : (k < 2.0 ? s.y : (k < 3.0 ? s.z : s.w));
}

// Patrones de escenario evaluados en el centro de cada LED (q en unidades del
// lado corto, centrado). Devuelven la intensidad del LED.
float pattern(float id, vec2 q, vec2 cell) {
  float t = uA.x;
  float kick = uA.z;
  float r = length(q);
  if (id < 0.5) {
    // Anillos que salen del centro.
    float rings = smoothstep(0.55, 0.95, sin(r * 22.0 - t * 5.0));
    return rings * (0.4 + 0.6 * uA.y + 0.5 * kick);
  }
  if (id < 1.5) {
    // Barridos diagonales cruzados.
    float a = smoothstep(0.6, 1.0, sin((q.x + q.y) * 9.0 - t * 4.0));
    float b = smoothstep(0.75, 1.0, sin((q.x - q.y) * 6.0 + t * 2.7));
    return a * 0.8 + b * 0.6 * (0.4 + uA.y);
  }
  if (id < 2.5) {
    // Barras del espectro en espejo desde el centro de la pantalla.
    float b = clamp(floor(abs(q.x) * 30.0), 0.0, 15.0);
    float level = 0.06 + 0.9 * band(b);
    float y = abs(q.y) / (0.5 * uSize.y / min(uSize.x, uSize.y));
    float bar = step(y, level);
    float cap = exp(-(y - level) * (y - level) * 4000.0);
    return bar * (0.45 + 0.55 * y / max(level, 0.05)) + cap * 1.4;
  }
  if (id < 3.5) {
    // Radar: haz giratorio con estela, anillos de referencia y núcleo.
    float behind = mod(atan(q.y, q.x) - uR.z, TAU);
    float beam = exp(-behind * 1.6) * (0.9 + 0.5 * kick);
    float grid = step(0.86, fract(r * 6.0)) * 0.3;
    return beam * smoothstep(0.02, 0.12, r) + grid + smoothstep(0.1, 0.0, r);
  }
  if (id < 4.5) {
    // Damero estroboscópico que alterna con cada golpe.
    vec2 block = floor(cell / 3.0);
    float parity = mod(block.x + block.y + uR.w, 2.0);
    return parity * (0.15 + 0.95 * kick) + (1.0 - parity) * 0.04;
  }
  // Plasma suave de escenario.
  float pl = sin(q.x * 7.0 + t * 1.3) + sin(q.y * 5.0 - t * 1.1) + sin((q.x + q.y) * 4.0 + t * 0.7);
  return smoothstep(1.4, 2.9, pl + 1.5) * (0.6 + 0.5 * uA.y + 0.4 * kick);
}

float wall(vec2 q, vec2 cell) {
  float next = pattern(uB.y, q, cell);
  if (uB.z >= 0.999) return next;
  return mix(pattern(uB.x, q, cell), next, uB.z);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  float pitch = scale / (22.0 + 6.0 * clamp(uD.w, 0.25, 2.0));
  vec2 cell = floor(frag / pitch);
  vec2 local = fract(frag / pitch) - 0.5;
  vec2 q = ((cell + 0.5) * pitch - 0.5 * uSize) / scale;
  vec2 qp = (frag - 0.5 * uSize) / scale;

  float I = wall(q, cell) * (0.85 + 0.6 * uA.z + 0.3 * uA.w);
  // Anillo blanco del golpe sobre cualquier patrón.
  float rq = length(q);
  I += uR.y * exp(-(rq - uR.x) * (rq - uR.x) * 140.0) * 1.5;
  // Brillo que se derrama entre LEDs: el patrón evaluado en el píxel.
  float spill = wall(qp, floor(frag / pitch));

  float d = length(local);
  float body = smoothstep(0.42, 0.30, d);
  float halo = exp(-d * d * 7.0);
  vec3 hot = mix(uC1, uC2, smoothstep(0.75, 1.4, I));
  vec3 col = uC0;
  col += uC3 * body * 0.10;                                  // LED apagado
  col += hot * I * (body * 1.1 + halo * 0.5 * uD.x);
  col += uC1 * spill * 0.10 * uD.x;
  // Destello blanco sólo en los LEDs encendidos.
  col += uC2 * uB.w * 0.5 * body * smoothstep(0.1, 0.6, I);
  // Titileo de LEDs sueltos con los agudos.
  float tw = step(0.993 - 0.01 * uD.y, hash12(cell + floor(uA.x * 8.0)));
  col += mix(uC1, uC2, 0.6) * tw * body * uD.y;

  col *= 1.0 - 0.3 * smoothstep(0.6, 1.4, length(qp * vec2(0.9, 0.65)));
  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.8) {
    float e = (peak - 0.8) / 0.2;
    col *= (0.8 + 0.2 * e / (1.0 + e)) / peak;
  }
  // Fondo transparente: color premultiplicado y opacidad según el brillo; la
  // luz muy tenue se vuelve transparente del todo para no dejar velo.
  col = clamp(col, 0.0, 1.0);
  float veilPeak = max(col.r, max(col.g, col.b));
  float clearCut = smoothstep(0.04, 0.12, veilPeak);
  col *= clearCut;
  float alpha = clamp(veilPeak * 1.25, 0.0, 1.0) * clearCut;
  fragColor = vec4(col, alpha);
}

visuals.nativeSource:
class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  float phase = 0, swirl = 0, hue = 0;
  std::array<float, 4> rings{};  // radio, amplitud, radio, amplitud

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    phase = rng.unit() * 20.0f;
    swirl = rng.unit() * 6.0f;
    hue = 0;
    rings = {3.0f, 0.0f, 3.0f, 0.0f};
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 20.0f, 4.0f, dt);
    body = follow(body, m.body, 10.0f, 2.5f, dt);
    spark = follow(spark, m.spark, 25.0f, 6.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      rings[2] = rings[0];
      rings[3] = rings[1];
      rings[0] = 0.0f;
      rings[1] = hit;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 7.0f), std::min(fl, 1.0f));
    for (int i = 0; i < 4; i += 2) {
      rings[i] += dt * (0.55f + 0.35f * drive);
      rings[i + 1] *= std::exp(-dt * 1.4f);
    }

    phase += dt * f.speed * (0.18f + 0.9f * drive + 0.7f * kick);
    swirl += dt * f.speed * (0.10f + 1.4f * bass + 0.8f * kick);
    hue += dt * (0.02f + 0.25f * body);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(28);
    u.insert(u.end(), {phase, swirl, bass * amp, kick * amp});
    u.insert(u.end(), {rings[0], rings[1] * amp, rings[2], rings[3] * amp});
    u.insert(u.end(), {hue, spark * amp, energy, f.glow});
    u.insert(u.end(), {flash, 0.6f + 0.4f * f.detail, 0.0f, 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("film", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.film:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // tiempo, remolino, graves, golpe
uniform vec4 uR;   // anillos: radio, amplitud, radio, amplitud
uniform vec4 uM;   // tono, agudos, energía, glow
uniform vec4 uX;   // destello, detalle
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

// Campana gaussiana segura: pow() con base negativa no está definido en GLSL.
float gauss(float x) {
  return exp(-x * x);
}

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

float fbm(vec2 p) {
  float s = 0.0;
  float a = 0.5;
  for (int i = 0; i < 4; i++) {
    s += a * noise(p);
    p = mat2(1.6, 1.2, -1.2, 1.6) * p;
    a *= 0.5;
  }
  return s;
}

float fbmLow(vec2 p) {
  float s = 0.0;
  float a = 0.5;
  for (int i = 0; i < 3; i++) {
    s += a * noise(p);
    p = mat2(1.6, 1.2, -1.2, 1.6) * p;
    a *= 0.5;
  }
  return s / 0.875 * 0.94;
}

vec2 rotate(vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  return vec2(c * p.x - s * p.y, s * p.x + c * p.y);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  p.y = -p.y;
  float t = uA.x;
  float r = length(p);

  // Remolinos: el dominio gira alrededor de tres vórtices que derivan.
  vec2 q = p;
  for (int i = 0; i < 3; i++) {
    float fi = float(i);
    vec2 c = vec2(sin(t * 0.13 + fi * 2.1), cos(t * 0.11 + fi * 1.7)) * vec2(0.32, 0.45);
    vec2 d = q - c;
    float w = exp(-dot(d, d) * 9.0);
    q = c + rotate(d, w * (1.2 + 0.9 * sin(uA.y * 0.35 + fi)) * (0.6 + uA.z * 1.6));
  }
  vec2 warp = vec2(fbmLow(q * 1.7 + vec2(0.0, t * 0.06)), fbmLow(q * 1.7 + vec2(5.2, -t * 0.05)));
  vec2 s = q + (warp - 0.5) * (0.55 + 0.6 * uA.z);
  float detail = fbm(s * (2.6 + 1.6 * uX.y) + vec2(t * 0.03, -t * 0.09));
  float fine = noise(s * 14.0 + vec2(0.0, -t * 0.5)) - 0.5;

  // Grosor (nm): la película drena hacia abajo; los graves la adelgazan en el centro.
  float thickness = 230.0 + 300.0 * smoothstep(0.55, -0.6, p.y);
  thickness += (detail - 0.5) * (330.0 + 220.0 * uA.z);
  thickness += fine * (18.0 + 80.0 * uM.y);
  thickness -= uA.z * 170.0 * exp(-r * r * 5.0);
  thickness += uR.y * 240.0 * gauss((r - uR.x) * 9.0);
  thickness += uR.w * 190.0 * gauss((r - uR.z) * 9.0);
  thickness += 80.0 * sin(uM.x * 6.2831853);
  // Película negra en la zona más fina, como en una pompa real.
  float black = smoothstep(120.0, 230.0, thickness);
  thickness = max(thickness, 0.0);

  // Color iridiscente: ciclo de tono por grosor, más vivo en los primeros órdenes.
  float order = thickness * 0.0029;
  vec3 iri = 0.5 + 0.5 * cos(6.2831853 * (order + vec3(0.0, 0.33, 0.67)));
  iri = pow(iri, vec3(1.5));
  float fadeOrders = exp(-thickness / 1100.0);
  vec3 film = iri * black * (0.55 + 0.75 * fadeOrders);
  // La luz que refleja la película varía a gran escala: zonas brillantes y oscuras.
  float sheen = 0.12 + 1.25 * smoothstep(0.35, 0.8, fbmLow(p * 0.9 + vec2(t * 0.02, 1.7)));
  float light = (0.24 + 0.15 * uM.z + 0.40 * uA.w) * sheen;
  vec3 col = uC0 + film * light * uM.w;

  // Arco especular suave: reflejo de una luz de anillo sobre la película.
  vec2 hp = p - vec2(-0.05, 0.10);
  float arc = gauss((length(hp * vec2(1.0, 1.25)) - 0.42) / 0.035);
  arc *= smoothstep(-0.2, 0.6, hp.y + hp.x * 0.3);
  col += uC3 * arc * (0.10 + 0.35 * uX.x + 0.25 * uA.w) * (0.6 + 0.4 * sheen);

  // Halo de color que acompaña a los anillos del golpe.
  col += mix(uC1, uC2, 0.5 + 0.5 * sin(t)) * uR.y * 0.25 * gauss((r - uR.x) * 6.0);

  col *= 1.0 - 0.45 * smoothstep(0.45, 1.3, length(p * vec2(0.85, 0.65)));
  col = clamp((col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14), 0.0, 1.0);
  col = pow(col, vec3(0.4545));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0, push = 0;
  std::array<float, 8> bands{};
  float spin = 0, orbit = 0, storm = 0;
  std::array<float, 4> waves{};  // radio, amplitud, radio, amplitud

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    bass = body = spark = energy = slowBass = kick = flash = drive = push = 0;
    bands.fill(0);
    spin = rng.unit() * 6.2831853f;
    orbit = rng.unit() * 0.6f - 0.3f;
    storm = rng.unit() * 10.0f;
    waves = {3.0f, 0.0f, 3.0f, 0.0f};
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 20.0f, 4.0f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    if (hit > kick + 0.2f) {
      waves[2] = waves[0];
      waves[3] = waves[1];
      waves[0] = 0.0f;
      waves[1] = hit;
    }
    kick = std::max(kick * std::exp(-dt * 4.5f), hit);
    flash = std::max(flash * std::exp(-dt * 6.0f), std::min(fl, 1.0f));
    for (int i = 0; i < 4; i += 2) {
      waves[i] += dt * 1.1f;
      waves[i + 1] *= std::exp(-dt * 1.3f);
    }

    static const int edges[9] = {0, 3, 6, 9, 13, 17, 21, 26, 31};
    for (int b = 0; b < 8; b++) {
      float v = 0;
      for (int i = edges[b]; i < edges[b + 1]; i++) v = std::max(v, m.smoothSpectrum[i]);
      bands[b] = follow(bands[b], v, 18.0f, 3.5f, dt);
    }

    spin += dt * f.speed * (0.04f + 0.25f * drive + 0.3f * kick);
    orbit += dt * f.speed * (0.015f + 0.05f * drive);
    storm += dt * f.speed * (0.05f + 0.6f * bass);
    push = follow(push, kick, 14.0f, 2.2f, dt);
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    std::vector<float> u;
    u.reserve(40);
    u.insert(u.end(), {spin, orbit, storm, push * amp});
    u.insert(u.end(), {bass * amp, kick * amp, energy, spark * amp});
    u.insert(u.end(), {waves[0], waves[1] * amp, waves[2], waves[3] * amp});
    u.insert(u.end(), {bands[0], bands[1], bands[2], bands[3]});
    u.insert(u.end(), {bands[4], bands[5], bands[6], bands[7]});
    u.insert(u.end(), {flash, f.glow, f.detail, 0.0f});
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("planet", {0, 0, f.width, f.height}, u);
  }
};

shaderSources.planet:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // giro del planeta, órbita de cámara, tormentas, empuje
uniform vec4 uB;   // graves, golpe, energía, agudos
uniform vec4 uW;   // ondas en los anillos: radio, amplitud, radio, amplitud
uniform vec4 uBands0;
uniform vec4 uBands1;
uniform vec4 uX;   // destello, glow, detalle
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

// Campana gaussiana segura: pow() con base negativa no está definido en GLSL.
float gauss(float x) {
  return exp(-x * x);
}

const float RING_IN = 1.38;
const float RING_OUT = 2.45;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float hash13(vec3 p3) {
  p3 = fract(p3 * 0.1031);
  p3 += dot(p3, p3.zyx + 31.32);
  return fract((p3.x + p3.y) * p3.z);
}

float noise3(vec3 x) {
  vec3 i = floor(x);
  vec3 f = fract(x);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(mix(hash13(i), hash13(i + vec3(1.0, 0.0, 0.0)), f.x),
                 mix(hash13(i + vec3(0.0, 1.0, 0.0)), hash13(i + vec3(1.0, 1.0, 0.0)), f.x), f.y),
             mix(mix(hash13(i + vec3(0.0, 0.0, 1.0)), hash13(i + vec3(1.0, 0.0, 1.0)), f.x),
                 mix(hash13(i + vec3(0.0, 1.0, 1.0)), hash13(i + vec3(1.0, 1.0, 1.0)), f.x), f.y), f.z);
}

float fbm3(vec3 p) {
  float s = 0.0;
  float a = 0.5;
  for (int i = 0; i < 4; i++) {
    s += a * noise3(p);
    p = p * 2.07 + vec3(3.1, 1.7, -2.3);
    a *= 0.5;
  }
  return s;
}

float noise1(float x) {
  float i = floor(x);
  float f = fract(x);
  return mix(hash12(vec2(i, 1.7)), hash12(vec2(i + 1.0, 1.7)), f * f * (3.0 - 2.0 * f));
}

float pick(float i) {
  if (i < 0.5) return uBands0.x;
  if (i < 1.5) return uBands0.y;
  if (i < 2.5) return uBands0.z;
  if (i < 3.5) return uBands0.w;
  if (i < 4.5) return uBands1.x;
  if (i < 5.5) return uBands1.y;
  if (i < 6.5) return uBands1.z;
  return uBands1.w;
}

float bandAt(float x) {
  float m = clamp(x, 0.0, 1.0) * 7.0;
  float i = floor(m);
  return mix(pick(i), pick(min(i + 1.0, 7.0)), smoothstep(0.0, 1.0, m - i));
}

// Densidad de los anillos: divisiones, huecos y ondas del golpe.
float ringDensity(float rho) {
  float inside = smoothstep(RING_IN, RING_IN + 0.06, rho) * smoothstep(RING_OUT, RING_OUT - 0.08, rho);
  float fine = 0.55 + 0.45 * noise1(rho * 46.0) * (0.7 + 0.3 * sin(rho * 180.0));
  float coarse = 0.6 + 0.4 * noise1(rho * 9.0 + 3.0);
  float gap = 1.0 - 0.92 * smoothstep(0.035, 0.0, abs(rho - 1.97));
  gap *= 1.0 - 0.6 * smoothstep(0.02, 0.0, abs(rho - 2.28));
  return inside * fine * coarse * gap;
}

vec3 rotateAxis(vec3 v, vec3 k, float a) {
  return v * cos(a) + cross(k, v) * sin(a) + k * dot(k, v) * (1.0 - cos(a));
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 uv = (frag - 0.5 * uSize) / scale;
  uv.y = -uv.y;

  vec3 axis = normalize(vec3(0.42, 1.0, 0.12));
  float az = 0.55 + uA.y;
  float el = 0.30;
  float dist = 6.2 - 0.9 * uA.w;
  vec3 ro = dist * vec3(cos(el) * sin(az), sin(el), -cos(el) * cos(az));
  vec3 fw = normalize(-ro);
  vec3 rt = normalize(cross(vec3(0.0, 1.0, 0.0), fw));
  vec3 up = cross(fw, rt);
  vec3 rd = normalize(fw * 2.0 + rt * uv.x + up * (uv.y + 0.04));
  vec3 sun = normalize(vec3(-0.8, 0.62, -0.35));
  float kick = uB.y;

  // Fondo: estrellas, polvo galáctico y resplandor del sol fuera de cuadro.
  vec3 col = uC0;
  vec2 g = uv * 110.0;
  float h = hash12(floor(g));
  float star = smoothstep(0.985, 1.0, h) * smoothstep(0.35, 0.0, length(fract(g) - 0.5));
  col += vec3(0.9, 0.93, 1.0) * star * (0.6 + 0.6 * sin(uA.x * 3.0 + h * 50.0) * uB.w + 0.4);
  col += uC2 * 0.05 * exp(-abs(uv.y + uv.x * 0.6 - 0.15) * 5.0);
  float sunGlow = pow(max(dot(rd, sun), 0.0), 12.0);
  col += uC3 * sunGlow * (0.15 + 0.2 * uX.x);

  // Planeta.
  float b = dot(ro, rd);
  float c = dot(ro, ro) - 1.0;
  float disc = b * b - c;
  float tP = disc > 0.0 ? -b - sqrt(disc) : 1e9;

  // Plano de los anillos.
  float denom = dot(rd, axis);
  float tR = abs(denom) > 1e-4 ? -dot(ro, axis) / denom : -1.0;
  vec3 hp = ro + rd * tR;
  float rho = length(hp);
  bool ringHit = tR > 0.0 && rho > RING_IN && rho < RING_OUT;

  if (tP < 1e8) {
    vec3 pos = ro + rd * tP;
    vec3 n = normalize(pos);
    float lat = dot(n, axis);
    vec3 nr = rotateAxis(n, axis, uA.x);
    float turb = fbm3(nr * vec3(2.2, 6.5, 2.2) + vec3(0.0, 0.0, uA.z * 0.15));
    float latw = lat + (turb - 0.5) * (0.07 + 0.06 * uB.x);
    float band = noise1(latw * 14.0 + 4.0) * 0.6 + noise1(latw * 37.0) * 0.4;
    vec3 surf = mix(uC1 * 0.65, uC3, smoothstep(0.2, 0.8, band));
    surf *= 0.85 + 0.3 * noise1(latw * 70.0 + 2.0);
    surf = mix(surf, mix(uC2, uC3, 0.5), smoothstep(0.62, 0.9, noise1(latw * 5.0 + 9.0)) * 0.25);
    // Gran tormenta ovalada que gira con el planeta.
    vec3 spotDir = normalize(vec3(0.62, -0.30, 0.72));
    vec3 sd = (nr - spotDir) * vec3(1.0, 2.4, 1.0);
    float spot = length(sd);
    surf = mix(surf, mix(uC1, uC3, 0.25) * 1.1, smoothstep(0.20, 0.12, spot));
    surf *= 1.0 - 0.35 * gauss((spot - 0.2) / 0.03);
    float diff = clamp(dot(n, sun) * 0.9 + 0.1, 0.0, 1.0);
    // Sombra de los anillos sobre el planeta.
    float ts = -dot(pos, axis) / dot(sun, axis);
    float shade = 1.0;
    if (ts > 0.0) {
      float rs = length(pos + sun * ts);
      shade = 1.0 - 0.75 * ringDensity(rs);
    }
    float limb = mix(0.5, 1.0, pow(max(dot(n, -rd), 0.0), 0.4));
    vec3 lit = surf * diff * shade * limb * 1.3;
    lit += surf * 0.03;
    float limbGlow = pow(1.0 - max(dot(n, -rd), 0.0), 5.0);
    lit += uC2 * limbGlow * (0.5 + 0.6 * uB.x + 0.9 * kick) * (0.3 + 0.7 * diff) * uX.y;
    // Óvalo auroral alrededor del polo, con cortinas suaves.
    float oval = gauss((abs(lat) - 0.86) / 0.035);
    float curtain = 0.4 + 0.6 * noise3(nr * 14.0 + vec3(0.0, uA.z * 0.8, 0.0));
    lit += mix(uC2, vec3(0.4, 1.0, 0.7), 0.5) * oval * curtain * (1.0 - diff) * (0.05 + 1.2 * kick) * uX.y;
    col = lit;
  }

  if (ringHit && tR < tP) {
    float dens = ringDensity(rho);
    float x = (rho - RING_IN) / (RING_OUT - RING_IN);
    float eq = bandAt(x);
    float wave = uW.y * gauss((rho - RING_IN - uW.x) * 10.0) +
                 uW.w * gauss((rho - RING_IN - uW.z) * 10.0);
    // Sombra del planeta sobre los anillos.
    float bb = dot(hp, sun);
    float cc = dot(hp, hp) - 1.0;
    float shadow = (bb < 0.0 && bb * bb - cc > 0.0) ? 0.12 : 1.0;
    float light = 0.45 + 0.55 * abs(dot(sun, axis));
    vec3 ringCol = mix(uC3, mix(uC1, uC2, x), 0.25 + 0.35 * eq);
    float glint = smoothstep(0.975, 1.0, hash12(floor(vec2(rho * 260.0, atan(hp.z, hp.x) * 140.0)) +
                                                floor(uA.x * 4.0))) * uB.w;
    // El ecualizador: cada banda enciende su anillo con un color propio.
    vec3 eqCol = mix(uC2, uC1, smoothstep(0.0, 1.0, x));
    vec3 rc = ringCol * dens * light * shadow * (0.5 + 0.3 * eq) +
              eqCol * dens * (eq * eq * 0.9 + wave * 1.6) +
              vec3(1.0) * glint * dens * 0.8;
    float alpha = clamp(dens * (0.75 + 0.25 * eq), 0.0, 0.95);
    col = mix(col, rc, alpha);
  }

  col += uC3 * uX.x * 0.12 * exp(-abs(uv.y - 0.3) * 18.0);
  col *= 1.0 - 0.35 * smoothstep(0.5, 1.3, length(uv * vec2(0.85, 0.7)));
  col = clamp((col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14), 0.0, 1.0);
  col = pow(col, vec3(0.4545));
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  float smoothBass = 0.0f;
  float smoothEnergy = 0.0f;
  float smoothSpark = 0.0f;
  float plasmaTime = 0.0f;
  float ripplePhase = 0.0f;
  float colorPhase = 0.0f;

 public:
  void reset(uint32_t) override {
    smoothBass = 0.0f;
    smoothEnergy = 0.0f;
    smoothSpark = 0.0f;
    plasmaTime = 0.0f;
    ripplePhase = 0.0f;
    colorPhase = 0.0f;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    if (dt > 0.1f) dt = 0.1f;

    // Filtro exponencial asimétrico para respuesta musical orgánica sin tirones
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetSpark = f.music.active ? f.music.spark : 0.0f;

    float bassRate = targetBass > smoothBass ? 16.0f : 4.5f;
    smoothBass += (targetBass - smoothBass) * (1.0f - std::exp(-dt * bassRate));
    smoothEnergy += (targetEnergy - smoothEnergy) * (1.0f - std::exp(-dt * 5.0f));
    smoothSpark += (targetSpark - smoothSpark) * (1.0f - std::exp(-dt * 10.0f));

    // Integración continua: la música modula la velocidad de flujo, nunca resetea la fase
    float speedMod = (1.0f + smoothEnergy * 0.75f + smoothBass * 0.5f) * f.speed;
    plasmaTime += dt * speedMod * 0.85f;
    ripplePhase += dt * (1.2f + smoothBass * 2.8f);
    colorPhase += dt * (0.04f + smoothBass * 0.10f + smoothEnergy * 0.06f);
  }

  void render(const Frame& f, Canvas& c) const override {
    c.material("plasma", {0, 0, f.width, f.height},
               {plasmaTime, ripplePhase, colorPhase, smoothBass, smoothEnergy, smoothSpark});
  }
};

shaderSources.plasma:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform float uTime;
uniform float uRipple;
uniform float uColorPhase;
uniform float uBass;
uniform float uEnergy;
uniform float uSpark;
out vec4 fragColor;

vec3 plasmaColor(float x) {
  float s = fract(x) * 8.0;
  int i = int(floor(s));
  float f = fract(s);
  f = f * f * (3.0 - 2.0 * f);

  vec3 c0 = vec3(0.005, 0.040, 0.120);
  vec3 c1 = vec3(0.000, 0.380, 0.580);
  vec3 c2 = vec3(0.000, 0.880, 0.760);
  vec3 c3 = vec3(0.500, 1.000, 0.380);
  vec3 c4 = vec3(1.000, 0.860, 0.220);
  vec3 c5 = vec3(1.000, 0.320, 0.300);
  vec3 c6 = vec3(0.960, 0.120, 0.680);
  vec3 c7 = vec3(0.240, 0.030, 0.380);

  vec3 colA = c0;
  vec3 colB = c1;
  if (i == 1) { colA = c1; colB = c2; }
  else if (i == 2) { colA = c2; colB = c3; }
  else if (i == 3) { colA = c3; colB = c4; }
  else if (i == 4) { colA = c4; colB = c5; }
  else if (i == 5) { colA = c5; colB = c6; }
  else if (i == 6) { colA = c6; colB = c7; }
  else if (i == 7) { colA = c7; colB = c0; }

  return mix(colA, colB, f);
}

void main() {
  vec2 uv = FlutterFragCoord().xy / uSize;
  float aspect = uSize.x / uSize.y;
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 6.5;

  vec2 c1 = vec2(sin(uTime * 0.45), cos(uTime * 0.38)) * 1.5;
  vec2 c2 = vec2(cos(uTime * 0.33 + 1.8), sin(uTime * 0.52)) * 1.4;

  float d1 = length(p - c1);
  float d2 = length(p - c2);

  float w1 = sin(p.x * 1.8 + uTime * 1.1);
  float w2 = sin(p.y * 2.1 + uTime * 0.95);
  float w3 = sin((p.x + p.y) * 1.5 + uTime * 0.75);
  float w4 = sin(d1 * 2.8 - uRipple * 2.2);
  float w5 = sin(d2 * 2.4 - uRipple * 1.7);

  vec2 warp = vec2(w1 + w5 * 0.4, w2 + w4 * 0.4) * (0.45 + uBass * 0.25);
  float w6 = sin(length(p + warp) * 2.6 - uTime * 1.2);

  float v = (w1 + w2 + w3 + w4 + w5 * 0.8 + w6 * 1.1) / 5.7;

  float phase = v * 0.85 + uColorPhase;
  vec3 col = plasmaColor(phase);

  float crest = pow(max(0.0, sin(v * 3.14159 * 2.0)), 6.0);
  vec3 filamentColor = mix(vec3(0.4, 0.8, 1.0), vec3(1.0, 0.9, 0.5), smoothstep(0.0, 1.0, uBass));
  col += filamentColor * (crest * (0.35 + uBass * 0.45 + uSpark * 0.4));

  col = mix(col, col * col * 1.4, uEnergy * 0.25);

  float vig = 1.0 - smoothstep(0.55, 1.4, length(uv - 0.5) * 1.35);
  col *= vig;

  fragColor = vec4(col, 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  float smoothBass = 0.0f;
  float smoothEnergy = 0.0f;
  float smoothSpark = 0.0f;
  float plasmaTime = 0.0f;
  float ripplePhase = 0.0f;
  float colorPhase = 0.0f;

 public:
  void reset(uint32_t) override {
    smoothBass = 0.0f;
    smoothEnergy = 0.0f;
    smoothSpark = 0.0f;
    plasmaTime = 0.0f;
    ripplePhase = 0.0f;
    colorPhase = 0.0f;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    if (dt > 0.1f) dt = 0.1f;

    // Filtro exponencial asimétrico para respuesta musical orgánica sin tirones
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetSpark = f.music.active ? f.music.spark : 0.0f;

    float bassRate = targetBass > smoothBass ? 16.0f : 4.5f;
    smoothBass += (targetBass - smoothBass) * (1.0f - std::exp(-dt * bassRate));
    smoothEnergy += (targetEnergy - smoothEnergy) * (1.0f - std::exp(-dt * 5.0f));
    smoothSpark += (targetSpark - smoothSpark) * (1.0f - std::exp(-dt * 10.0f));

    // Integración continua: la música modula la velocidad de flujo, nunca resetea la fase
    float speedMod = (1.0f + smoothEnergy * 0.75f + smoothBass * 0.5f) * f.speed;
    plasmaTime += dt * speedMod * 0.85f;
    ripplePhase += dt * (1.2f + smoothBass * 2.8f);
    colorPhase += dt * (0.04f + smoothBass * 0.10f + smoothEnergy * 0.06f);
  }

  void render(const Frame& f, Canvas& c) const override {
    c.material("plasma", {0, 0, f.width, f.height},
               {plasmaTime, ripplePhase, colorPhase, smoothBass, smoothEnergy, smoothSpark});
  }
};

shaderSources.plasma:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform float uTime;
uniform float uRipple;
uniform float uColorPhase;
uniform float uBass;
uniform float uEnergy;
uniform float uSpark;
out vec4 fragColor;

vec3 plasmaColor(float x) {
  float s = fract(x) * 8.0;
  int i = int(floor(s));
  float f = fract(s);
  f = f * f * (3.0 - 2.0 * f);

  vec3 c0 = vec3(0.005, 0.040, 0.120);
  vec3 c1 = vec3(0.000, 0.380, 0.580);
  vec3 c2 = vec3(0.000, 0.880, 0.760);
  vec3 c3 = vec3(0.500, 1.000, 0.380);
  vec3 c4 = vec3(1.000, 0.860, 0.220);
  vec3 c5 = vec3(1.000, 0.320, 0.300);
  vec3 c6 = vec3(0.960, 0.120, 0.680);
  vec3 c7 = vec3(0.240, 0.030, 0.380);

  vec3 colA = c0;
  vec3 colB = c1;
  if (i == 1) { colA = c1; colB = c2; }
  else if (i == 2) { colA = c2; colB = c3; }
  else if (i == 3) { colA = c3; colB = c4; }
  else if (i == 4) { colA = c4; colB = c5; }
  else if (i == 5) { colA = c5; colB = c6; }
  else if (i == 6) { colA = c6; colB = c7; }
  else if (i == 7) { colA = c7; colB = c0; }

  return mix(colA, colB, f);
}

void main() {
  vec2 uv = FlutterFragCoord().xy / uSize;
  float aspect = uSize.x / uSize.y;
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 6.5;

  vec2 c1 = vec2(sin(uTime * 0.45), cos(uTime * 0.38)) * 1.5;
  vec2 c2 = vec2(cos(uTime * 0.33 + 1.8), sin(uTime * 0.52)) * 1.4;

  float d1 = length(p - c1);
  float d2 = length(p - c2);

  float w1 = sin(p.x * 1.8 + uTime * 1.1);
  float w2 = sin(p.y * 2.1 + uTime * 0.95);
  float w3 = sin((p.x + p.y) * 1.5 + uTime * 0.75);
  float w4 = sin(d1 * 2.8 - uRipple * 2.2);
  float w5 = sin(d2 * 2.4 - uRipple * 1.7);

  vec2 warp = vec2(w1 + w5 * 0.4, w2 + w4 * 0.4) * (0.45 + uBass * 0.25);
  float w6 = sin(length(p + warp) * 2.6 - uTime * 1.2);

  float v = (w1 + w2 + w3 + w4 + w5 * 0.8 + w6 * 1.1) / 5.7;

  float phase = v * 0.85 + uColorPhase;
  vec3 col = plasmaColor(phase);

  float crest = pow(max(0.0, sin(v * 3.14159 * 2.0)), 6.0);
  vec3 filamentColor = mix(vec3(0.4, 0.8, 1.0), vec3(1.0, 0.9, 0.5), smoothstep(0.0, 1.0, uBass));
  col += filamentColor * (crest * (0.35 + uBass * 0.45 + uSpark * 0.4));

  col = mix(col, col * col * 1.4, uEnergy * 0.25);

  float vig = 1.0 - smoothstep(0.55, 1.4, length(uv - 0.5) * 1.35);
  col *= vig;

  float alpha = smoothstep(-0.25, 0.45, v);
  fragColor = vec4(col * alpha, alpha);
}

visuals.nativeSource:
class Visual final : public Scene {
  static constexpr int kBursts = 4;
  struct Burst { float x = 0, y = 0, size = 0, seed = 0, hue = 0; double born = -100; };
  std::array<Burst, kBursts> bursts{};
  int next = 0, count = 0, beats = 0;
  float bass = 0, body = 0, spark = 0, energy = 0, slowBass = 0;
  float kick = 0, flash = 0, drive = 0;
  // Reloj propio en doble precisión; las nubes se describen por su edad, así
  // que la escena es idéntica a 30 y a 60 FPS.
  double clock = 0, nextAuto = 0.4, sinceDrop = 100;
  Random rng{41};

  static float follow(float v, float target, float up, float down, float dt) {
    return v + (target - v) * (1.0f - std::exp(-(target > v ? up : down) * dt));
  }

  static float hash(float n) {
    float x = std::sin(n) * 43758.5453f;
    return x - std::floor(x);
  }

  void spawn(double born, float size) {
    Burst& b = bursts[next];
    next = (next + 1) % kBursts;
    b.x = (rng.unit() - 0.5f) * 0.8f;
    b.y = (rng.unit() - 0.5f) * 1.2f;
    b.size = size * (0.85f + 0.4f * rng.unit());
    b.seed = rng.unit() * 50.0f;
    // Colores en turno con algún tono intermedio.
    b.hue = float(count % 3) + (rng.unit() < 0.3f ? 0.5f : 0.0f);
    b.born = born;
    count++;
  }

  // Edad, radio, desvanecido y posición de una nube.
  void state(const Burst& b, float& age, float& radius, float& fade, float& x, float& y) const {
    age = float(clock - b.born);
    radius = b.size * (0.12f + 0.88f * (1.0f - std::exp(-age * 2.0f))) + 0.025f * age;
    fade = std::exp(-age * 0.7f) * std::clamp(age / 0.06f, 0.0f, 1.0f);
    x = b.x;
    y = b.y - 0.03f * age + 0.004f * age * age;
  }

 public:
  void reset(uint32_t seed) override {
    rng = Random(seed);
    bursts = {};
    next = count = beats = 0;
    bass = body = spark = energy = slowBass = kick = flash = drive = 0;
    clock = 0;
    nextAuto = 0.4;
    sinceDrop = 100;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    const Music& m = f.music;
    bass = follow(bass, m.bass, 22.0f, 4.5f, dt);
    body = follow(body, m.body, 12.0f, 3.0f, dt);
    spark = follow(spark, m.spark, 30.0f, 7.0f, dt);
    energy = follow(energy, m.energy, 6.0f, 1.8f, dt);
    drive = follow(drive, m.active ? std::pow(std::clamp(m.energy, 0.0f, 1.0f), 0.8f) : 0.0f, 3.0f, 0.7f, dt);

    float hit = 0, fl = 0;
    for (const auto& e : m.events[0]) hit = std::max(hit, e.strength);
    for (const auto& e : m.events[2]) hit = std::max(hit, e.strength * 0.85f);
    for (const auto& e : m.events[3]) fl = std::max(fl, e.strength);
    float onset = std::clamp((m.bass - slowBass - 0.15f) * 2.5f, 0.0f, 1.0f);
    slowBass = follow(slowBass, m.bass, 3.0f, 3.0f, dt);
    hit = std::min(std::max(hit, onset), 1.0f);
    clock += f.delta * f.speed;
    sinceDrop += f.delta;
    if (hit > kick + 0.2f) {
      if (hit > 0.7f && drive > 0.4f && sinceDrop > 6.0) {
        // Drop: dos nubes grandes a la vez.
        for (int i = 0; i < 2; i++) spawn(clock, 0.5f);
        sinceDrop = 0;
      } else if (hit > 0.8f || (++beats % 2) == 0) {
        // Una nube cada dos golpes (o en cada golpe fuerte): menos capas a la vez.
        spawn(clock, 0.3f + 0.15f * hit);
      }
      nextAuto = clock + 1.8;
    }
    // Sin golpes (silencio o música tranquila): una nube suave cada 2,4 s.
    while (clock >= nextAuto) {
      spawn(nextAuto, 0.38f);
      nextAuto += 2.4;
    }
    kick = std::max(kick * std::exp(-dt * 5.0f), hit);
    flash = std::max(flash * std::exp(-dt * 8.0f), std::min(fl, 1.0f));
  }

  void render(const Frame& f, Canvas& c) const override {
    float amp = f.intensity;
    float s = std::min(f.width, f.height);
    // Nubes de la más antigua a la más reciente: la nueva queda delante.
    std::array<int, kBursts> order;
    for (int i = 0; i < kBursts; i++) order[i] = i;
    std::stable_sort(order.begin(), order.end(), [&](int a, int b) { return bursts[a].born < bursts[b].born; });
    std::vector<float> u;
    u.reserve(52);
    u.insert(u.end(), {float(std::fmod(clock, 1000.0)), bass * amp, kick * amp, energy});
    u.insert(u.end(), {f.glow, spark * amp, flash * amp, 0.0f});
    for (int k = 0; k < kBursts; k++) {
      const Burst& b = bursts[order[k]];
      float age, radius, fade, x, y;
      state(b, age, radius, fade, x, y);
      if (b.born < -50) fade = 0;
      u.insert(u.end(), {x, y, radius, std::max(0.0f, fade) * amp});
      u.insert(u.end(), {age, b.seed, b.hue, 0.0f});
    }
    for (int i = 0; i < 4; i++) u.insert(u.end(), {f.colors[i].r, f.colors[i].g, f.colors[i].b});
    c.material("powder", {0, 0, f.width, f.height}, u);

    // Granos que salen disparados de cada explosión.
    for (int k = 0; k < kBursts; k++) {
      const Burst& b = bursts[order[k]];
      if (b.born < -50) continue;
      float age, radius, fade, x, y;
      state(b, age, radius, fade, x, y);
      float life = 1.0f - age / 3.5f;
      if (life <= 0) continue;
      std::vector<Vec2> grains;
      grains.reserve(90);
      for (int i = 0; i < 90; i++) {
        float a = hash(b.seed * 7.1f + float(i) * 1.37f) * 6.2831853f;
        float speed = b.size * (0.6f + 1.4f * hash(b.seed * 3.3f + float(i) * 2.11f));
        float dist = speed * (1.0f - std::exp(-age * 2.4f)) / 2.4f * 2.2f;
        float gx = b.x + std::cos(a) * dist;
        float gy = b.y + std::sin(a) * dist + 0.05f * age * age;
        grains.push_back({f.width * 0.5f + gx * s, f.height * 0.5f + gy * s});
      }
      float hue = b.hue;
      int ci = int(std::floor(hue)) % 3;
      const Color& col = f.colors[1 + ci];
      Paint dust;
      dust.blend = Blend::plus;
      dust.color = {std::min(1.0f, col.r + 0.3f), std::min(1.0f, col.g + 0.3f), std::min(1.0f, col.b + 0.3f),
                    std::clamp(life * fade * (0.5f + 0.6f * spark) * amp, 0.0f, 1.0f)};
      c.points(grains, (1.0f + 0.6f * spark * amp) * s / 400.0f, dust);
    }
  }
};

shaderSources.powder:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec4 uA;   // reloj, graves, golpe, energía
uniform vec4 uB;   // glow, agudos, destello
uniform vec4 uP0;  // nubes de la más antigua a la más reciente: centro, radio, intensidad
uniform vec4 uQ0;  // edad, semilla, tono
uniform vec4 uP1;
uniform vec4 uQ1;
uniform vec4 uP2;
uniform vec4 uQ2;
uniform vec4 uP3;
uniform vec4 uQ3;
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uC3;
out vec4 fragColor;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

vec3 tone(float h) {
  float k = mod(h, 3.0);
  vec3 a = k < 1.0 ? uC1 : (k < 2.0 ? uC2 : uC3);
  vec3 b = k < 1.0 ? uC2 : (k < 2.0 ? uC3 : uC1);
  return mix(a, b, smoothstep(0.0, 1.0, fract(k)));
}

// Una nube de polvo: borde deshilachado por ruido, volutas que giran con la
// edad y un núcleo más denso y luminoso al principio de la explosión.
vec4 cloud(vec2 p, vec4 P, vec4 Q) {
  if (P.w < 0.005) return vec4(0.0);
  vec2 d = (p - P.xy) / P.z;
  float r = length(d);
  if (r > 1.5) return vec4(0.0);
  float age = Q.x;
  vec2 q = d * 2.6 + Q.y;
  vec2 drift = vec2(age * 0.2, -age * 0.15);
  float w = noise(q * 0.8 + drift);
  vec2 qq = q + vec2(w * 1.8, -age * 0.25);
  float n = noise(qq * 1.6);
  // Volutas con relieve: la diferencia entre el ruido y su deformación hace
  // de luz y sombra.
  float light = clamp(0.6 + (n - w) * 1.3, 0.0, 1.2);
  float edge = r + (n - 0.5) * 1.05;
  float dens = smoothstep(1.0, 0.3, edge) * (0.55 + 0.7 * n);
  float core = exp(-r * r * 6.0) * exp(-age * 1.5);
  float a = clamp(dens * P.w * 1.25, 0.0, 0.97);
  // El polvo conserva su color vivo al desvanecerse: se aclara, no se oscurece.
  vec3 c = tone(Q.z) * (0.7 + 0.6 * light + 0.4 * uA.y) * (0.75 + 0.25 * P.w);
  c = mix(c, vec3(1.0), core * 0.5 + 0.12 * light * n);
  return vec4(c, a);
}

vec3 over(vec3 col, vec4 layer) {
  return mix(col, layer.rgb, layer.a);
}

void main() {
  vec2 frag = FlutterFragCoord().xy;
  float scale = min(uSize.x, uSize.y);
  vec2 p = (frag - 0.5 * uSize) / scale;
  vec3 col = uC0;
  col = over(col, cloud(p, uP0, uQ0));
  col = over(col, cloud(p, uP1, uQ1));
  col = over(col, cloud(p, uP2, uQ2));
  col = over(col, cloud(p, uP3, uQ3));
  col += vec3(1.0) * uB.z * 0.04;
  col *= 1.0 - 0.35 * smoothstep(0.6, 1.4, length(p * vec2(0.9, 0.65)));
  // Compresión suave que conserva el tono vivo del polvo.
  float peak = max(col.r, max(col.g, col.b));
  if (peak > 0.8) {
    float e = (peak - 0.8) / 0.2;
    col *= (0.8 + 0.2 * e / (1.0 + e)) / peak;
  }
  col += (hash12(frag) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

visuals.shaderSource:
vec2 rotate2D(vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

vec3 paletteCos(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
  return a + b * cos(6.28318 * (c * t + d));
}

vec4 paintVisual(vec2 uv, CreatorFrame f) {
  float aspect = max(f.size.x, 1.0) / max(f.size.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 2.2;

  float bass = clamp(f.bass, 0.0, 1.0);
  float energy = clamp(f.energy, 0.0, 1.0);
  float spark = clamp(f.spark, 0.0, 1.0);
  float flow = clamp(f.flow, 0.0, 1.0);

  float t = f.time * f.speed * 0.42;
  vec3 col = vec3(0.0);

  // Split into 3 chromatic channels for subtle optical dispersion
  for (int ch = 0; ch < 3; ch++) {
    float dispersion = float(ch - 1) * (0.012 + 0.022 * spark);
    vec2 cp = p * (1.0 + dispersion);

    float r = length(cp);
    // Logarithmic tunnel coordinate moving into the screen
    float z = 1.0 / (r + 0.06);
    float tunnelDepth = z * 0.55 - t * (1.1 + 0.9 * energy);

    // Dynamic rotation modulated by sub-bass and flow
    vec2 q = rotate2D(cp, t * 0.25 + z * 0.12 + bass * 0.35);

    // Iterated Sacred Geometry / Kaleidoscope Folding
    float accum = 0.0;
    vec2 k = q * (1.8 + 0.4 * flow);
    for (int i = 0; i < 4; i++) {
      float fi = float(i);
      k = abs(k) - vec2(0.32 + 0.12 * sin(t * 0.6 + fi * 1.3), 0.22 + 0.08 * cos(t * 0.45));
      k = rotate2D(k, 0.785398 + 0.25 * bass + fi * 0.3);
      accum += 1.0 / (length(k) * 22.0 + 1.0);
    }

    // Glowing harmonic tunnel rings
    float ringPattern = abs(sin(tunnelDepth * 3.14159));
    float ringGlow = (0.025 + 0.035 * bass) / (ringPattern * ringPattern + 0.007);

    // Center singularity core radiance
    float core = (0.10 + 0.35 * bass) / (r * r * 18.0 + 0.12);

    // Color ramp: electric cyan, deep magenta, warm gold
    vec3 pal = paletteCos(
      tunnelDepth * 0.16 + float(ch) * 0.06 + t * 0.05,
      vec3(0.5, 0.5, 0.5),
      vec3(0.5, 0.5, 0.5),
      vec3(1.0, 1.0, 1.0),
      vec3(0.05, 0.33, 0.67)
    );

    float intensity = (accum * 0.42 + ringGlow * 0.48 + core * 0.6) * f.intensity * f.glow;

    if (ch == 0) col.r += intensity * pal.r;
    else if (ch == 1) col.g += intensity * pal.g;
    else if (ch == 2) col.b += intensity * pal.b;
  }

  // Soft tone mapping and subtle cinematic vignette
  col = col / (col + vec3(0.85));
  float vignette = 1.0 - smoothstep(0.45, 1.45, length(p));
  col *= vignette;

  return vec4(col, 1.0);
}

vec2 rotate2D(vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

vec3 paletteCos(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
  return a + b * cos(6.28318 * (c * t + d));
}

vec4 paintVisual(vec2 uv, CreatorFrame f) {
  float aspect = max(f.size.x, 1.0) / max(f.size.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 2.2;

  float bass = clamp(f.bass, 0.0, 1.0);
  float energy = clamp(f.energy, 0.0, 1.0);
  float spark = clamp(f.spark, 0.0, 1.0);
  float flow = clamp(f.flow, 0.0, 1.0);

  float t = f.time * f.speed * 0.42;
  vec3 col = vec3(0.0);

  // Split into 3 chromatic channels for subtle optical dispersion
  for (int ch = 0; ch < 3; ch++) {
    float dispersion = float(ch - 1) * (0.012 + 0.022 * spark);
    vec2 cp = p * (1.0 + dispersion);

    float r = length(cp);
    // Logarithmic tunnel coordinate moving into the screen
    float z = 1.0 / (r + 0.06);
    float tunnelDepth = z * 0.55 - t * (1.1 + 0.9 * energy);

    // Dynamic rotation modulated by sub-bass and flow
    vec2 q = rotate2D(cp, t * 0.25 + z * 0.12 + bass * 0.35);

    // Iterated Sacred Geometry / Kaleidoscope Folding
    float accum = 0.0;
    vec2 k = q * (1.8 + 0.4 * flow);
    for (int i = 0; i < 4; i++) {
      float fi = float(i);
      k = abs(k) - vec2(0.32 + 0.12 * sin(t * 0.6 + fi * 1.3), 0.22 + 0.08 * cos(t * 0.45));
      k = rotate2D(k, 0.785398 + 0.25 * bass + fi * 0.3);
      accum += 1.0 / (length(k) * 22.0 + 1.0);
    }

    // Glowing harmonic tunnel rings
    float ringPattern = abs(sin(tunnelDepth * 3.14159));
    float ringGlow = (0.025 + 0.035 * bass) / (ringPattern * ringPattern + 0.007);

    // Center singularity core radiance
    float core = (0.10 + 0.35 * bass) / (r * r * 18.0 + 0.12);

    // Color ramp: electric cyan, deep magenta, warm gold
    vec3 pal = paletteCos(
      tunnelDepth * 0.16 + float(ch) * 0.06 + t * 0.05,
      vec3(0.5, 0.5, 0.5),
      vec3(0.5, 0.5, 0.5),
      vec3(1.0, 1.0, 1.0),
      vec3(0.05, 0.33, 0.67)
    );

    float intensity = (accum * 0.42 + ringGlow * 0.48 + core * 0.6) * f.intensity * f.glow;

    if (ch == 0) col.r += intensity * pal.r;
    else if (ch == 1) col.g += intensity * pal.g;
    else if (ch == 2) col.b += intensity * pal.b;
  }

  // Soft tone mapping and subtle cinematic vignette
  col = col / (col + vec3(0.85));
  float vignette = 1.0 - smoothstep(0.45, 1.45, length(p));
  col *= vignette;

  // RGBA recto: el motor multiplica por alpha al componer.
  float alpha = clamp(max(col.r, max(col.g, col.b)) * 1.6, 0.0, 1.0);
  return vec4(clamp(col, 0.0, 1.0), alpha);
}

vec4 paintVisual(vec2 uv, CreatorFrame f) {
  vec2 p = (uv - 0.5) * vec2(f.size.x / max(f.size.y, 1.0), 1.0);
  float radius = 0.27 + 0.015 * sin(f.time * f.speed) + 0.025 * f.bass;
  float distance = abs(length(p) - radius);
  float beam = exp(-distance * distance * 17000.0);
  float halo = exp(-distance * 24.0) * 0.25 * f.glow;
  float alpha = clamp((beam * 0.62 + halo) * f.intensity * (0.8 + 0.2 * f.pulse), 0.0, 1.0);
  vec3 ink = mix(f.color1.rgb, f.color2.rgb, 0.5 + 0.5 * sin(p.x * 7.0 + f.time * 0.2));
  return vec4(ink, alpha);
}

