      ep.strokeWidth = std::clamp(1.2f + (1.0f - depthNorm) * 2.0f, 0.8f, 3.2f);

      Path edgePath;
      edgePath.moveTo(p1.x, p1.y);
      edgePath.lineTo(p2.x, p2.y);
      c.path(edgePath, ep);
    }

    // 3. Renderizar los 16 vértices cuatridimensionales
    for (int i = 0; i < 16; i++) {
      Vec2 pt = projected[i];
      float z = depths[i];
      float depthNorm = std::clamp((z + 1.2f) / 2.4f, 0.0f, 1.0f);
      float rad = std::clamp(2.0f + (1.0f - depthNorm) * 3.5f, 1.5f, 5.5f);

      // Halo del vértice
      Paint vHalo; vHalo.blend = Blend::plus;
      vHalo.color = {0.0f, 1.0f, 0.88f, std::clamp(0.40f * f.intensity, 0.0f, 1.0f)};
      c.circle(pt, rad * 2.0f, vHalo);

      // Núcleo blanco del vértice
      Paint vCore; vCore.blend = Blend::plus;
      vCore.color = {1.0f, 1.0f, 1.0f, std::clamp(0.92f * f.intensity, 0.0f, 1.0f)};
      c.circle(pt, rad, vCore);
    }
  }
};

class Visual final : public Scene {
  static constexpr int kRibbons = 5;
  static constexpr int kSteps = 24;
  struct Star { float x, y, phase; };
  std::vector<Star> stars;
  float auroraTime = 0.0f;
  float smoothBass = 0.0f;
  float smoothEnergy = 0.0f;
 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    stars.clear(); stars.reserve(70);
    auroraTime = 0.0f;
    smoothBass = 0.0f;
    smoothEnergy = 0.0f;
    for (int i = 0; i < 70; i++) {
      stars.push_back({rng.unit(), rng.unit() * 0.72f, rng.unit() * 6.2831853f});
    }
  }
  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 5.0));
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));

    // En silencio reposa en un oleaje majestuoso de noche polar (~0.12f).
    // Con música acelera la danza de viento solar ionizado y pulsa la amplitud.
    float audioDrive = 0.12f + smoothEnergy * 0.75f + smoothBass * 0.35f;
    auroraTime += dt * f.speed * audioDrive;
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float t = auroraTime;
    float centerX = w * 0.5f;

    // 1. Fondo cielo polar
    Paint sky = Paint::linear({centerX, 0.0f}, {centerX, h},
      {Color::argb(0xff010610), Color::argb(0xff03141f), Color::argb(0xff000508)},
      {0.0f, 0.5f, 1.0f});
    c.rect({0, 0, w, h}, sky);

    // 2. Estrellas con centelleo polar
    std::vector<Vec2> starPts;
    starPts.reserve(stars.size());
    for (const auto& s : stars) {
      starPts.push_back({s.x * w, s.y * h});
    }
    float twinkle = 0.35f + 0.35f * std::sin(t * 2.2f);
    Paint starPaint; starPaint.blend = Blend::plus;
    starPaint.color = {1.0f, 1.0f, 1.0f, std::clamp((0.25f + twinkle) * f.intensity, 0.0f, 1.0f)};
    c.points(starPts, 1.2f, starPaint);

    // 3. Cortinas de plasma ionizado
    const uint32_t rCols[kRibbons][2] = {
      {0xff00ffa3, 0xff00d2ff},
      {0xff00e5ff, 0xff7000ff},
      {0xff00ff77, 0xff00c6ff},
      {0xff9d4edd, 0xffff007f},
      {0xff00ffb2, 0xff3a86ff}
    };

    float stepW = w / float(kSteps - 1);
    float solarWind = 1.0f + smoothBass * 0.35f;

    for (int r = 0; r < kRibbons; r++) {
      float phaseOffset = float(r) * 1.25f;
      float baseY = h * 0.22f + float(r) * (h * 0.09f);

      Path ribbonPath;
      Vec2 pts[kSteps];
      for (int i = 0; i < kSteps; i++) {
        float x = float(i) * stepW;
        float normX = x / w;

        float w1 = std::sin(normX * 4.0f + t * 0.8f + phaseOffset) * 45.0f * solarWind;
        float w2 = std::cos(normX * 8.0f - t * 0.6f + phaseOffset) * 25.0f * solarWind;
        float w3 = std::sin(normX * 12.0f + t * 1.2f) * 12.0f;
        float y = baseY + w1 + w2 + w3;
        pts[i] = Vec2{x, y};
      }

      // Trazar spline suave
      ribbonPath.moveTo(pts[0].x, pts[0].y);
      for (int i = 0; i < kSteps - 1; i++) {
        float mx = (pts[i].x + pts[i + 1].x) * 0.5f;
        float my = (pts[i].y + pts[i + 1].y) * 0.5f;
        ribbonPath.quadraticTo(pts[i].x, pts[i].y, mx, my);
      }
      ribbonPath.lineTo(pts[kSteps - 1].x, pts[kSteps - 1].y);

      Color c1 = Color::argb(rCols[r][0]);
      Color c2 = Color::argb(rCols[r][1]);

      // Velo ancho difuso de plasma (múltiples pasadas para crear volumen)
      float strokeW = (32.0f - float(r) * 3.5f) * (h / 600.0f);
      Paint ribbonGlow; ribbonGlow.blend = Blend::plus;
      ribbonGlow.color = {c1.r, c1.g, c1.b, std::clamp(0.22f * f.intensity, 0.0f, 1.0f)};
      ribbonGlow.strokeWidth = strokeW * 1.8f;
      ribbonGlow.strokeCap = 1; ribbonGlow.strokeJoin = 1;
      c.path(ribbonPath, ribbonGlow);

      Paint ribbonMid; ribbonMid.blend = Blend::plus;
      ribbonMid.color = {c2.r, c2.g, c2.b, std::clamp(0.38f * f.intensity, 0.0f, 1.0f)};
      ribbonMid.strokeWidth = strokeW;
      ribbonMid.strokeCap = 1; ribbonMid.strokeJoin = 1;
      c.path(ribbonPath, ribbonMid);

      // Filamento central brillante
      Paint coreFilament; coreFilament.blend = Blend::plus;
      coreFilament.color = {1.0f, 1.0f, 1.0f, std::clamp(0.48f * f.intensity, 0.0f, 1.0f)};
      coreFilament.strokeWidth = 2.4f;
      coreFilament.strokeCap = 1; coreFilament.strokeJoin = 1;
      c.path(ribbonPath, coreFilament);
    }

    // 4. Siluetas montañosas en primer plano
    Path mountains;
    mountains.moveTo(0.0f, h);
    mountains.lineTo(0.0f, h * 0.84f);
    mountains.lineTo(w * 0.22f, h * 0.76f);
    mountains.lineTo(w * 0.45f, h * 0.82f);
    mountains.lineTo(w * 0.72f, h * 0.73f);
    mountains.lineTo(w, h * 0.86f);
    mountains.lineTo(w, h);
    mountains.close();

    Paint mountainPaint; mountainPaint.color = Color::argb(0xff010408);
    c.path(mountains, mountainPaint);
  }
};

class Visual final : public Scene {
  static constexpr int kBarCount = 72;
  float spectralTime = 0.0f;
  float smoothEnergy = 0.0f;
  float smoothBass = 0.0f;
 public:
  void reset(uint32_t seed) override {
    (void)seed;
    spectralTime = 0.0f;
    smoothEnergy = 0.0f;
    smoothBass = 0.0f;
  }
  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 6.0));
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 8.0));

    // En silencio reposa en un orbe tranquilo (~0.08f).
    // Con música la rotación y el pulso se acoplan a la señal.
    float audioDrive = 0.08f + smoothEnergy * 0.72f + smoothBass * 0.35f;
    spectralTime += dt * f.speed * audioDrive;
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float t = spectralTime;
    Vec2 center{w * 0.5f, h * 0.5f};
    float minDim = std::min(w, h);

    // 1. Fondo cósmico radial
    Paint bg = Paint::radial(center, minDim * 0.9f,
      {Color::argb(0xff130324), Color::argb(0xff06010d), Color::argb(0xff000000)},
      {0.0f, 0.45f, 1.0f});
    c.rect({0, 0, w, h}, bg);

    // 2. Núcleo central pulsante: en silencio está sereno (kick = 0)
    float kick = (f.music.active ? smoothBass * 1.5f : 0.0f) * f.intensity;
    float baseRadius = minDim * 0.12f * (1.0f + kick * 0.28f);

    // Resplandor del núcleo
    float glowAlpha = f.music.active ? (0.25f + smoothEnergy * 0.35f) : 0.15f;
    Paint coreGlow = Paint::radial(center, baseRadius * 1.6f,
      {{1.0f, 0.0f, 0.5f, std::clamp(glowAlpha * f.intensity, 0.0f, 1.0f)}, {0, 0, 0, 0}},
      {0.0f, 1.0f});
    coreGlow.blend = Blend::plus;
    c.circle(center, baseRadius * 1.6f, coreGlow);

    // Esfera interior del núcleo
    Paint coreSphere = Paint::radial(center, baseRadius * 0.85f,
      {Color{1.0f, 1.0f, 1.0f, 1.0f}, Color::argb(0xff00f0ff), Color::argb(0xff7000ff)},
      {0.0f, 0.4f, 1.0f});
    coreSphere.blend = Blend::plus;
    c.circle(center, baseRadius * 0.85f, coreSphere);

    // 3. Renderizar las 72 barras radiales
    const float angleStep = 6.2831853f / float(kBarCount);
    std::vector<Vec2> sparkCaps;
    sparkCaps.reserve(kBarCount);

    for (int i = 0; i < kBarCount; i++) {
      float angle = float(i) * angleStep - 3.14159265f * 0.5f;

      // Frecuencia normalizada (sub-graves simétricos y agudos laterales)
      float normFreq = std::abs((float(i) / (float(kBarCount) * 0.5f)) - 1.0f);
      int specIdx = std::clamp(int(normFreq * 30.0f), 0, 30);
      float realAudio = f.music.active ? f.music.spectrum[specIdx] : 0.0f;
      float smoothAudio = f.music.active ? f.music.smoothSpectrum[specIdx] : 0.0f;

      // En silencio las barras descansan en un anillo limpio sin brincar a lo loco
      float barVal = f.music.active ? std::max(realAudio * 1.8f, smoothAudio * 1.3f) : 0.015f;
      float barLength = minDim * (0.018f + barVal * 0.18f + kick * (1.0f - normFreq) * 0.12f);

      float cosA = std::cos(angle), sinA = std::sin(angle);
      float sx = center.x + baseRadius * cosA;
      float sy = center.y + baseRadius * sinA;
      float ex = center.x + (baseRadius + barLength) * cosA;
      float ey = center.y + (baseRadius + barLength) * sinA;

      // Color lerp: cian {0, 1, 0.88} a magenta {1, 0, 0.33}
      Color barCol{
        0.0f * (1.0f - normFreq) + 1.0f * normFreq,
        1.0f * (1.0f - normFreq) + 0.0f * normFreq,
        0.88f * (1.0f - normFreq) + 0.33f * normFreq,
        std::clamp(0.85f * f.intensity, 0.0f, 1.0f)
      };
      Paint bp; bp.blend = Blend::plus; bp.color = barCol;
      bp.strokeWidth = std::max(1.2f, minDim * 0.008f);
      bp.strokeCap = 1;

      Path barPath; barPath.moveTo(sx, sy); barPath.lineTo(ex, ey);
      c.path(barPath, bp);

      // Chispas en los picos de energía
      if (barLength > minDim * 0.14f) {
        float spx = center.x + (baseRadius + barLength + 4.0f) * cosA;
        float spy = center.y + (baseRadius + barLength + 4.0f) * sinA;
        sparkCaps.push_back({spx, spy});
      }
    }

    if (!sparkCaps.empty()) {
      Paint spk; spk.blend = Blend::plus;
      spk.color = {1.0f, 1.0f, 1.0f, std::clamp(0.95f * f.intensity, 0.0f, 1.0f)};
      c.points(sparkCaps, 2.0f, spk);
    }

    // 4. Anillo de resonancia exterior
    float ringRadius = baseRadius + minDim * 0.22f;
    Paint ringPaint; ringPaint.blend = Blend::plus;
    ringPaint.color = {0.0f, 1.0f, 0.88f, std::clamp(0.25f * f.intensity, 0.0f, 1.0f)};
    ringPaint.strokeWidth = 1.4f;
    c.circle(center, ringRadius, ringPaint);

    // 5. Partículas armónicas en órbita
    std::vector<Vec2> orbiters;
    orbiters.reserve(8);
    for (int p = 0; p < 8; p++) {
      float pAngle = t * (0.8f + float(p) * 0.2f) + float(p) * (3.14159265f / 4.0f);
      float radOffset = std::sin(pAngle * 3.0f) * 12.0f;
      float ox = center.x + (ringRadius + radOffset) * std::cos(pAngle);
      float oy = center.y + (ringRadius + radOffset) * std::sin(pAngle);
      orbiters.push_back({ox, oy});
    }
    Paint orbPaint; orbPaint.blend = Blend::plus;
    orbPaint.color = {1.0f, 0.0f, 0.63f, std::clamp(0.85f * f.intensity, 0.0f, 1.0f)};
    c.points(orbiters, 2.8f, orbPaint);
  }
};

