class Visual final : public Scene {
  struct CorruptRow {
    float baseShift;
    float blockWidth;
    float blockHeight;
    float chromaOffset;
    float seedPhase;
    float burstShift;
    float burstLife;
    bool hasAlert;
  };

  std::vector<CorruptRow> rows;
  float simTime = 0.0f;
  float lastBurstTime = -10.0f;
  float sparkChromaTimer = 0.0f;
  float trackingY = 0.88f;
  float smoothEnergy = 0.0f;
  float smoothBass = 0.0f;

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    rows.clear();
    rows.reserve(90);
    simTime = 0.0f;
    lastBurstTime = -10.0f;
    sparkChromaTimer = 0.0f;
    trackingY = 0.88f;
    smoothEnergy = 0.0f;
    smoothBass = 0.0f;

    for (int i = 0; i < 90; i++) {
      CorruptRow r;
      r.baseShift = (rng.unit() - 0.5f) * 24.0f;
      r.blockWidth = 8.0f + rng.unit() * 32.0f;
      r.blockHeight = 2.0f + rng.unit() * 4.0f;
      r.chromaOffset = 4.0f + rng.unit() * 14.0f;
      r.seedPhase = rng.unit() * 6.2831853f;
      r.burstShift = 0.0f;
      r.burstLife = 0.0f;
      r.hasAlert = rng.unit() < 0.14f;
      rows.push_back(r);
    }
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    float targetSpark = f.music.active ? f.music.spark : 0.0f;

    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));

    // En silencio reposa en un barrido CRT limpio con mínima deriva (~0.12f).
    // Con música acelera el datamosh glitch y los saltos cromáticos.
    float audioDrive = 0.12f + smoothEnergy * 0.72f + smoothBass * 0.35f;
    float speedMult = (f.reducedMotion ? 0.25f : 1.0f) * f.speed * audioDrive;
    simTime += dt * speedMult;

    // Detección de ráfaga de desplazamiento en bombos fuertes con música activa
    if (f.music.active && (targetSpark > 0.65f || smoothBass > 0.72f) && (simTime - lastBurstTime >= 1.8f)) {
      lastBurstTime = simTime;
      Random burstRng(uint32_t(simTime * 1000.0f) ^ 0x30303);
      int centerRow = int(burstRng.unit() * 70.0f) + 10;
      for (int i = 0; i < 90; i++) {
        if (std::abs(i - centerRow) < 22 || burstRng.unit() < 0.28f) {
          rows[i].burstLife = 0.30f;
          float sgn = burstRng.unit() > 0.5f ? 1.0f : -1.0f;
          rows[i].burstShift = sgn * (28.0f + burstRng.unit() * 65.0f);
        }
      }
    }

    // Salto cromático de 120ms en chispas agudas con música activa
    if (f.music.active && targetSpark > 0.60f) {
      sparkChromaTimer = 0.12f;
    }
    if (sparkChromaTimer > 0.0f) {
      sparkChromaTimer = std::max(0.0f, sparkChromaTimer - dt);
    }

    for (auto& r : rows) {
      if (r.burstLife > 0.0f) {
        r.burstLife = std::max(0.0f, r.burstLife - dt);
      }
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float time = simTime;

    // 1. Degradado base cyberpunk: #0a0a12 a #1a1030
    Paint bg = Paint::linear({0.0f, 0.0f}, {0.0f, h},
      {Color::argb(0xff0a0a12), Color::argb(0xff120d22), Color::argb(0xff1a1030)},
      {0.0f, 0.5f, 1.0f});
    c.rect({0, 0, w, h}, bg);

    // Barrido CRT: líneas horizontales sutiles cada 4px
    Paint scanline;
    scanline.color = {0.02f, 0.015f, 0.04f, 0.45f};
    scanline.strokeWidth = 1.4f;
    Path scanlines;
    for (float y = 0.0f; y < h; y += 4.0f) {
      scanlines.moveTo(0.0f, y);
      scanlines.lineTo(w, y);
    }
    c.path(scanlines, scanline);

    float chromaJump = sparkChromaTimer > 0.0f ? 18.0f * (sparkChromaTimer / 0.12f) : 0.0f;
    float densityThreshold = 0.25f + smoothEnergy * 0.58f;
    float rowStep = h / 90.0f;

    Path pathR, pathB, pathLuma, pathAlert;

    for (int i = 0; i < 90; i++) {
      const auto& r = rows[i];

      // Onda de datamosh continuo
      float structuralWave =
        std::sin(float(i) * 0.16f + time * 1.8f + r.seedPhase) *
        std::cos(float(i) * 0.05f - time * 0.9f);
      float activeScore = std::abs(structuralWave) + (r.burstLife > 0.0f ? 0.8f : 0.0f);
      if (activeScore < 1.0f - densityThreshold) continue;

      float y = float(i) * rowStep;
      float bh = r.blockHeight;
      float bw = r.blockWidth * (w / 380.0f);
      float burstFactor = r.burstLife / 0.30f;
      float shiftX = w * 0.5f + structuralWave * (w * 0.26f) + r.baseShift + r.burstShift * burstFactor;
      float cOff = r.chromaOffset + chromaJump + burstFactor * 12.0f;

      int clusterCount = r.burstLife > 0.0f ? 4 : 2;
      for (int k = 0; k < clusterCount; k++) {
        float bx = shiftX + float(k - 1) * (bw * 1.35f);

        // Canal Rojo desplazado hacia la izquierda
        pathR.rect({bx - cOff, y, bw, bh});

        // Canal Azul desplazado hacia la derecha
        float yOffB = sparkChromaTimer > 0.0f ? 2.0f : 0.0f;
        pathB.rect({bx + cOff, y + yOffB, bw, bh});

        // Bloque central Luma
        pathLuma.rect({bx, y, bw * 0.78f, bh});

        if (r.hasAlert && k == 0 && (r.burstLife > 0.0f || structuralWave > 0.65f)) {
          pathAlert.rect({bx + bw * 0.9f, y, 10.0f, bh + 1.0f});
        }
      }
    }

    // Dibujado aditivo de canales RGB
    float boost = std::clamp((0.75f + smoothEnergy * 0.35f) * f.intensity, 0.0f, 1.0f);

    // Canal Magenta #ff2e88
    Paint pR; pR.blend = Blend::plus;
    pR.color = {1.0f, 0.18f, 0.53f, std::clamp(0.78f * boost, 0.0f, 1.0f)};
    c.path(pathR, pR);

    // Canal Cian #00f0ff
    Paint pB; pB.blend = Blend::plus;
    pB.color = {0.0f, 0.94f, 1.0f, std::clamp(0.78f * boost, 0.0f, 1.0f)};
    c.path(pathB, pB);

    // Canal Luma claro
    Paint pLuma; pLuma.blend = Blend::plus;
    pLuma.color = {0.90f, 0.94f, 1.0f, std::clamp(0.42f * boost, 0.0f, 1.0f)};
    c.path(pathLuma, pLuma);

    // Canal de alertas doradas #ffe14d
    Paint pAlert; pAlert.blend = Blend::plus;
    pAlert.color = {1.0f, 0.88f, 0.30f, std::clamp(0.95f * boost, 0.0f, 1.0f)};
    c.path(pathAlert, pAlert);

    // 2. Franja VHS rodante de sincronismo inferior
    float trackNormY = 0.89f + 0.04f * std::sin(time * 1.7f);
    float trackY = h * trackNormY;
    float trackH = 18.0f + smoothBass * 14.0f;

    Paint trackGrad = Paint::linear({0.0f, trackY}, {0.0f, trackY + trackH},
      {{1.0f, 0.18f, 0.53f, 0.0f},
       {0.0f, 0.94f, 1.0f, std::clamp(0.35f * boost, 0.0f, 1.0f)},
       {1.0f, 0.18f, 0.53f, std::clamp(0.45f * boost, 0.0f, 1.0f)},
       {0.04f, 0.04f, 0.07f, 0.0f}},
      {0.0f, 0.35f, 0.65f, 1.0f});
    trackGrad.blend = Blend::plus;
    c.rect({0, trackY, w, trackH}, trackGrad);

    // Rasgaduras de sincronismo horizontales en la franja
    Path tearPath;
    for (int k = 0; k < 6; k++) {
      float sliceX = std::fmod(time * 220.0f + float(k) * 83.0f, w + 40.0f) - 20.0f;
      tearPath.rect({sliceX, trackY + float(k) * 2.5f, 36.0f, 1.8f});
    }
    Paint tearPaint; tearPaint.blend = Blend::plus;
    tearPaint.color = {1.0f, 0.88f, 0.30f, std::clamp(0.55f * boost, 0.0f, 1.0f)};
    c.path(tearPath, tearPaint);
  }
};

class Visual final : public Scene {
  struct CorruptRow {
    float baseShift;
    float blockWidth;
    float blockHeight;
    float chromaOffset;
    float seedPhase;
    float burstShift;
    float burstLife;
    bool hasAlert;
  };

  std::vector<CorruptRow> rows;
  float simTime = 0.0f;
  float lastBurstTime = -10.0f;
  float sparkChromaTimer = 0.0f;
  float trackingY = 0.88f;
  float smoothEnergy = 0.0f;
  float smoothBass = 0.0f;

 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    rows.clear();
    rows.reserve(90);
    simTime = 0.0f;
    lastBurstTime = -10.0f;
    sparkChromaTimer = 0.0f;
    trackingY = 0.88f;
    smoothEnergy = 0.0f;
    smoothBass = 0.0f;

    for (int i = 0; i < 90; i++) {
      CorruptRow r;
      r.baseShift = (rng.unit() - 0.5f) * 24.0f;
      r.blockWidth = 8.0f + rng.unit() * 32.0f;
      r.blockHeight = 2.0f + rng.unit() * 4.0f;
      r.chromaOffset = 4.0f + rng.unit() * 14.0f;
      r.seedPhase = rng.unit() * 6.2831853f;
      r.burstShift = 0.0f;
      r.burstLife = 0.0f;
      r.hasAlert = rng.unit() < 0.14f;
      rows.push_back(r);
    }
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    float targetSpark = f.music.active ? f.music.spark : 0.0f;

    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));

    // En silencio reposa en un barrido CRT limpio con mínima deriva (~0.12f).
    // Con música acelera el datamosh glitch y los saltos cromáticos.
    float audioDrive = 0.12f + smoothEnergy * 0.72f + smoothBass * 0.35f;
    float speedMult = (f.reducedMotion ? 0.25f : 1.0f) * f.speed * audioDrive;
    simTime += dt * speedMult;

    // Detección de ráfaga de desplazamiento en bombos fuertes con música activa
    if (f.music.active && (targetSpark > 0.65f || smoothBass > 0.72f) && (simTime - lastBurstTime >= 1.8f)) {
      lastBurstTime = simTime;
      Random burstRng(uint32_t(simTime * 1000.0f) ^ 0x30303);
      int centerRow = int(burstRng.unit() * 70.0f) + 10;
      for (int i = 0; i < 90; i++) {
        if (std::abs(i - centerRow) < 22 || burstRng.unit() < 0.28f) {
          rows[i].burstLife = 0.30f;
          float sgn = burstRng.unit() > 0.5f ? 1.0f : -1.0f;
          rows[i].burstShift = sgn * (28.0f + burstRng.unit() * 65.0f);
        }
      }
    }

    // Salto cromático de 120ms en chispas agudas con música activa
    if (f.music.active && targetSpark > 0.60f) {
      sparkChromaTimer = 0.12f;
    }
    if (sparkChromaTimer > 0.0f) {
      sparkChromaTimer = std::max(0.0f, sparkChromaTimer - dt);
    }

    for (auto& r : rows) {
      if (r.burstLife > 0.0f) {
        r.burstLife = std::max(0.0f, r.burstLife - dt);
      }
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float time = simTime;

    // Sin fondo opaco: lienzo 100% transparente para efecto HUD / filtro glitch

    float chromaJump = sparkChromaTimer > 0.0f ? 18.0f * (sparkChromaTimer / 0.12f) : 0.0f;
    float densityThreshold = 0.25f + smoothEnergy * 0.58f;
    float rowStep = h / 90.0f;

    Path pathR, pathB, pathLuma, pathAlert;

    for (int i = 0; i < 90; i++) {
      const auto& r = rows[i];

      // Onda de datamosh continuo
      float structuralWave =
        std::sin(float(i) * 0.16f + time * 1.8f + r.seedPhase) *
        std::cos(float(i) * 0.05f - time * 0.9f);
      float activeScore = std::abs(structuralWave) + (r.burstLife > 0.0f ? 0.8f : 0.0f);
      if (activeScore < 1.0f - densityThreshold) continue;

      float y = float(i) * rowStep;
      float bh = r.blockHeight;
      float bw = r.blockWidth * (w / 380.0f);
      float burstFactor = r.burstLife / 0.30f;
      float shiftX = w * 0.5f + structuralWave * (w * 0.26f) + r.baseShift + r.burstShift * burstFactor;
      float cOff = r.chromaOffset + chromaJump + burstFactor * 12.0f;

      int clusterCount = r.burstLife > 0.0f ? 4 : 2;
      for (int k = 0; k < clusterCount; k++) {
        float bx = shiftX + float(k - 1) * (bw * 1.35f);

        // Canal Rojo desplazado hacia la izquierda
        pathR.rect({bx - cOff, y, bw, bh});

        // Canal Azul desplazado hacia la derecha
        float yOffB = sparkChromaTimer > 0.0f ? 2.0f : 0.0f;
        pathB.rect({bx + cOff, y + yOffB, bw, bh});

        // Bloque central Luma
        pathLuma.rect({bx, y, bw * 0.78f, bh});

        if (r.hasAlert && k == 0 && (r.burstLife > 0.0f || structuralWave > 0.65f)) {
          pathAlert.rect({bx + bw * 0.9f, y, 10.0f, bh + 1.0f});
        }
      }
    }

    // Dibujado aditivo de canales RGB
    float boost = std::clamp((0.75f + smoothEnergy * 0.35f) * f.intensity, 0.0f, 1.0f);

    // Canal Magenta #ff2e88
    Paint pR; pR.blend = Blend::plus;
    pR.color = {1.0f, 0.18f, 0.53f, std::clamp(0.78f * boost, 0.0f, 1.0f)};
    c.path(pathR, pR);

    // Canal Cian #00f0ff
    Paint pB; pB.blend = Blend::plus;
    pB.color = {0.0f, 0.94f, 1.0f, std::clamp(0.78f * boost, 0.0f, 1.0f)};
    c.path(pathB, pB);

    // Canal Luma claro
    Paint pLuma; pLuma.blend = Blend::plus;
    pLuma.color = {0.90f, 0.94f, 1.0f, std::clamp(0.42f * boost, 0.0f, 1.0f)};
    c.path(pathLuma, pLuma);

    // Canal de alertas doradas #ffe14d
    Paint pAlert; pAlert.blend = Blend::plus;
    pAlert.color = {1.0f, 0.88f, 0.30f, std::clamp(0.95f * boost, 0.0f, 1.0f)};
    c.path(pathAlert, pAlert);

    // Franja VHS rodante de sincronismo inferior
    float trackNormY = 0.89f + 0.04f * std::sin(time * 1.7f);
    float trackY = h * trackNormY;
    float trackH = 18.0f + smoothBass * 14.0f;

    Paint trackGrad = Paint::linear({0.0f, trackY}, {0.0f, trackY + trackH},
      {{1.0f, 0.18f, 0.53f, 0.0f},
       {0.0f, 0.94f, 1.0f, std::clamp(0.35f * boost, 0.0f, 1.0f)},
       {1.0f, 0.18f, 0.53f, std::clamp(0.45f * boost, 0.0f, 1.0f)},
       {0.04f, 0.04f, 0.07f, 0.0f}},
      {0.0f, 0.35f, 0.65f, 1.0f});
    trackGrad.blend = Blend::plus;
    c.rect({0, trackY, w, trackH}, trackGrad);

    // Rasgaduras de sincronismo horizontales en la franja
    Path tearPath;
    for (int k = 0; k < 6; k++) {
      float sliceX = std::fmod(time * 220.0f + float(k) * 83.0f, w + 40.0f) - 20.0f;
      tearPath.rect({sliceX, trackY + float(k) * 2.5f, 36.0f, 1.8f});
    }
    Paint tearPaint; tearPaint.blend = Blend::plus;
    tearPaint.color = {1.0f, 0.88f, 0.30f, std::clamp(0.55f * boost, 0.0f, 1.0f)};
    c.path(tearPath, tearPaint);
  }
};

class Visual final : public Scene {
  struct Planet {
    float radiusRatio;
    float size;
    float basePeriod;
    float inclination;
    float tiltAngle;
    bool retrograde;
    Color color;
    float angle;
  };

  std::vector<Planet> planets;
  float clockTime = 0.0f;
  float smoothEnergy = 0.0f;
  float smoothBass = 0.0f;
  float smoothSpark = 0.0f;

 public:
  void reset(uint32_t seed) override {
    (void)seed;
    planets.clear();
    planets.reserve(4);
    clockTime = 0.0f;
    smoothEnergy = 0.0f;
    smoothBass = 0.0f;
    smoothSpark = 0.0f;

    // Cobre
    planets.push_back({0.19f, 8.5f, 14.0f, 0.0f, 0.20f, false, {0.85f, 0.55f, 0.29f, 1.0f}, 0.8f});
    // Bronce
    planets.push_back({0.27f, 7.0f, 8.5f, 0.36f, 0.65f, false, {0.72f, 0.63f, 0.42f, 1.0f}, 2.3f});
    // Acero
    planets.push_back({0.35f, 9.5f, 11.2f, 0.42f, -0.50f, false, {0.44f, 0.62f, 0.77f, 1.0f}, 4.1f});
    // Jade (retrogrado)
    planets.push_back({0.42f, 6.5f, 6.8f, 0.15f, 1.10f, true, {0.37f, 0.75f, 0.63f, 1.0f}, 5.4f});
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    float targetSpark = f.music.active ? f.music.spark : 0.0f;
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));
    smoothSpark += (targetSpark - smoothSpark) * float(1.0 - std::exp(-dt * 15.0));

    // En silencio reposa en un tic-tac de reloj celestial sereno y majestuoso (~0.12f).
    // Con música la maquinaria de relojería se revoluciona al compás del ritmo.
    float audioDrive = 0.12f + smoothEnergy * 0.76f + smoothBass * 0.35f;
    float speedFactor = (f.reducedMotion ? 0.25f : 1.0f) * f.speed * audioDrive;
    clockTime += dt * speedFactor;

    for (auto& p : planets) {
      float dir = p.retrograde ? -1.0f : 1.0f;
      p.angle += dir * (6.2831853f / p.basePeriod) * dt * speedFactor;
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float minDim = std::min(w, h);
    Vec2 center{w * 0.5f, h * 0.5f};
    float time = clockTime;
    float boost = std::clamp((0.85f + smoothEnergy * 0.35f) * f.intensity, 0.0f, 1.0f);

    // 1. Fondo de piedra tallada #14100c con núcleo ámbar
    Paint bg = Paint::radial(center, minDim * 0.75f,
      {Color::argb(0xff1e1812), Color::argb(0xff14100c), Color::argb(0xff090705)},
      {0.0f, 0.55f, 1.0f});
    c.rect({0, 0, w, h}, bg);

    // Barras diagonales estructurales de latón
    Paint crossbar;
    crossbar.color = {0.42f, 0.35f, 0.23f, std::clamp(0.28f * boost, 0.0f, 1.0f)};
    crossbar.strokeWidth = 1.5f;
    Path cross;
    for (int a = 0; a < 4; a++) {
      float ang = (float(a) * 3.14159265f * 0.5f) + 0.785398f;
      cross.moveTo(center.x + std::cos(ang) * minDim * 0.07f, center.y + std::sin(ang) * minDim * 0.07f);
      cross.lineTo(center.x + std::cos(ang) * minDim * 0.46f, center.y + std::sin(ang) * minDim * 0.46f);
    }
    c.path(cross, crossbar);

    // 2. Bisel exterior de la corona graduada con 96 muescas y glifos
    float crownTilt = (f.music.flow - 0.5f) * 0.16f;
    float outerR = minDim * 0.455f;
    float innerR = minDim * 0.415f;

    c.save();
    c.translate(center.x, center.y);
    c.rotate(crownTilt);

    // Aros del bisel
    Paint bezel;
    bezel.color = {0.72f, 0.63f, 0.42f, std::clamp(0.38f * boost, 0.0f, 1.0f)};
    bezel.strokeWidth = 1.8f;
    c.circle({0, 0}, outerR, bezel);
    c.circle({0, 0}, innerR, bezel);

    // 96 marcas graduadas en el bisel
    Path ticks;
    for (int i = 0; i < 96; i++) {
      float ang = (float(i) / 96.0f) * 6.2831853f;
      bool isMajor = (i % 8 == 0);
      float r0 = isMajor ? innerR : innerR + (outerR - innerR) * 0.45f;
      ticks.moveTo(std::cos(ang) * r0, std::sin(ang) * r0);
      ticks.lineTo(std::cos(ang) * outerR, std::sin(ang) * outerR);
    }
    Paint tickPaint;
    tickPaint.color = {0.72f, 0.63f, 0.42f, std::clamp(0.48f * boost, 0.0f, 1.0f)};
    tickPaint.strokeWidth = 1.0f;
    c.path(ticks, tickPaint);

    // 12 Glifos geométricos abstractos
    float midRingR = (outerR + innerR) * 0.5f;
    float glyphR = minDim * 0.012f;
    Path glyphsPath;
    for (int s = 0; s < 12; s++) {
      float ang = (float(s) / 12.0f) * 6.2831853f + 0.130899f;
      float gx = std::cos(ang) * midRingR;
      float gy = std::sin(ang) * midRingR;

      if (s % 3 == 0) {
        // Rombo con punto central
        glyphsPath.moveTo(gx, gy - glyphR);
        glyphsPath.lineTo(gx + glyphR, gy);
        glyphsPath.lineTo(gx, gy + glyphR);
        glyphsPath.lineTo(gx - glyphR, gy);
        glyphsPath.close();
      } else if (s % 3 == 1) {
        // Círculo / bisector
        glyphsPath.circle({gx, gy}, glyphR * 0.75f);
      } else {
        // Triángulo
        glyphsPath.moveTo(gx, gy - glyphR);
        glyphsPath.lineTo(gx + glyphR * 0.9f, gy + glyphR * 0.8f);
        glyphsPath.lineTo(gx - glyphR * 0.9f, gy + glyphR * 0.8f);
        glyphsPath.close();
      }
    }
    Paint glyphPaint;
    glyphPaint.color = {0.85f, 0.55f, 0.29f, std::clamp(0.65f * boost, 0.0f, 1.0f)};
    glyphPaint.strokeWidth = 1.2f;
    c.path(glyphsPath, glyphPaint);

    // 4 Tornillos ranurados de latón en diagonales
    Paint screwHead; screwHead.color = Color::argb(0xff8b734b);
    Paint screwSlot; screwSlot.color = Color::argb(0xff14100c); screwSlot.strokeWidth = 1.2f;
    for (int k = 0; k < 4; k++) {
      float ang = float(k) * 1.570796f + 0.785398f;
      float sx = std::cos(ang) * (innerR - minDim * 0.018f);
      float sy = std::sin(ang) * (innerR - minDim * 0.018f);
      c.circle({sx, sy}, 4.5f, screwHead);
      Path slot; slot.moveTo(sx - 3.0f, sy - 3.0f); slot.lineTo(sx + 3.0f, sy + 3.0f);
      c.path(slot, screwSlot);
    }

    c.restore();

    // 3. Órbitas elípticas inclinadas con desvanecimiento de profundidad
    for (const auto& p : planets) {
      float orbitR = minDim * p.radiusRatio;
      float cosTilt = std::cos(p.tiltAngle);
      float sinTilt = std::sin(p.tiltAngle);
      float squash = 1.0f - p.inclination * 0.32f;

      for (int half = 0; half < 2; half++) {
        Path orbitHalf;
        int startSeg = half == 0 ? 0 : 64;
        int endSeg = half == 0 ? 64 : 128;
        for (int s = startSeg; s <= endSeg; s++) {
          float theta = (float(s) / 128.0f) * 6.2831853f;
          float lx = std::cos(theta) * orbitR;
          float ly = std::sin(theta) * orbitR * squash;
          float rx = center.x + lx * cosTilt - ly * sinTilt;
          float ry = center.y + lx * sinTilt + ly * cosTilt;
          if (s == startSeg) orbitHalf.moveTo(rx, ry);
          else orbitHalf.lineTo(rx, ry);
        }
        Paint op;
        float alpha = (half == 0 ? 0.35f : 0.14f) * boost;
        op.color = {0.42f, 0.35f, 0.23f, std::clamp(alpha, 0.0f, 1.0f)};
        op.strokeWidth = 1.35f;
        c.path(orbitHalf, op);
      }
    }

    // 4. Sol central iluminado
    float sunR = minDim * 0.056f;
    float bassGlow = std::clamp((0.25f + smoothBass * 0.75f) * f.intensity, 0.0f, 1.0f);

    Paint sunCorona = Paint::radial(center, sunR * 2.8f,
      {{1.0f, 0.88f, 0.59f, std::clamp(0.85f * boost, 0.0f, 1.0f)},
       {0.85f, 0.55f, 0.29f, std::clamp(0.28f * boost, 0.0f, 1.0f)},
       {0, 0, 0, 0}}, {0.0f, 0.45f, 1.0f});
    sunCorona.blend = Blend::plus;
    c.circle(center, sunR * 2.8f, sunCorona);

    Paint sunBody = Paint::radial({center.x - sunR * 0.3f, center.y - sunR * 0.3f}, sunR,
      {Color::argb(0xfffff4d2), Color::argb(0xffd99b4a), Color::argb(0xff6b4820)},
      {0.0f, 0.6f, 1.0f});
    c.circle(center, sunR, sunBody);

    // Índice dorado giratorio esmaltado (reloj mecánico)
    c.save();
    c.translate(center.x, center.y);
    c.rotate(time * 0.25f);
    Path needle;
    needle.moveTo(0.0f, -sunR * 1.30f);
    needle.lineTo(sunR * 0.28f, 0.0f);
    needle.lineTo(0.0f, sunR * 0.55f);
    needle.lineTo(-sunR * 0.28f, 0.0f);
    needle.close();
    Paint needlePaint;
    needlePaint.color = {1.0f, 0.85f, 0.35f, bassGlow};
    needlePaint.blend = Blend::plus;
    c.path(needle, needlePaint);
    c.restore();

    // 5. Esferas planetarias con sombra arrojada, halo y destello spark
    for (const auto& p : planets) {
      float orbitR = minDim * p.radiusRatio;
      float cosTilt = std::cos(p.tiltAngle);
      float sinTilt = std::sin(p.tiltAngle);
      float squash = 1.0f - p.inclination * 0.32f;

      float lx = std::cos(p.angle) * orbitR;
      float ly = std::sin(p.angle) * orbitR * squash;
      float px = center.x + lx * cosTilt - ly * sinTilt;
      float py = center.y + lx * sinTilt + ly * cosTilt;

      float depthScale = 1.0f + std::sin(p.angle) * p.inclination * 0.22f;
      float pr = p.size * (minDim / 420.0f) * depthScale;

      float dx = px - center.x;
      float dy = py - center.y;
      float dist = std::sqrt(dx * dx + dy * dy);
      if (dist < 1.0f) dist = 1.0f;
      float nx = dx / dist;
      float ny = dy / dist;

      // Sombra cónica arrojada hacia el exterior
      Path shadowPoly;
      shadowPoly.moveTo(px - ny * pr * 0.9f, py + nx * pr * 0.9f);
      shadowPoly.lineTo(px + ny * pr * 0.9f, py - nx * pr * 0.9f);
      shadowPoly.lineTo(px + nx * pr * 3.6f + ny * pr * 0.4f, py + ny * pr * 3.6f - nx * pr * 0.4f);
      shadowPoly.lineTo(px + nx * pr * 3.6f - ny * pr * 0.4f, py + ny * pr * 3.6f + nx * pr * 0.4f);
      shadowPoly.close();

      Paint shadowPaint = Paint::linear({px, py}, {px + nx * pr * 3.6f, py + ny * pr * 3.6f},
        {{0.02f, 0.02f, 0.01f, std::clamp(0.78f * boost, 0.0f, 1.0f)}, {0.02f, 0.02f, 0.01f, 0.0f}},
        {0.0f, 1.0f});
      c.path(shadowPoly, shadowPaint);

      // Halo atmosférico del planeta
      float haloR = pr * (2.6f + smoothSpark * 1.8f);
      Paint halo = Paint::radial({px, py}, haloR,
        {{p.color.r, p.color.g, p.color.b, std::clamp(0.55f * boost, 0.0f, 1.0f)},
         {p.color.r, p.color.g, p.color.b, 0.0f}}, {0.0f, 1.0f});
      halo.blend = Blend::plus;
      c.circle({px, py}, haloR, halo);

      // Esfera 3D iluminada hacia el sol central
      float lightX = px - nx * pr * 0.42f;
      float lightY = py - ny * pr * 0.42f;
      Paint spherePaint = Paint::radial({lightX, lightY}, pr * 1.35f,
        {{1.0f, 0.99f, 0.96f, 1.0f},
         p.color,
         Color::argb(0xff120f0b)}, {0.0f, 0.45f, 1.0f});
      c.circle({px, py}, pr, spherePaint);

      // Destello en chispas agudas (90ms)
      if (smoothSpark > 0.02f) {
        Paint sparkPaint; sparkPaint.blend = Blend::plus;
        sparkPaint.color = {1.0f, 0.98f, 0.92f, std::clamp(smoothSpark * 0.90f * f.intensity, 0.0f, 1.0f)};
        c.circle({px, py}, pr * (1.0f + smoothSpark * 0.55f), sparkPaint);
      }
    }
  }
};

class Visual final : public Scene {
  struct Planet {
    float radiusRatio;
    float size;
    float basePeriod;
    float inclination;
    float tiltAngle;
    bool retrograde;
    Color color;
    float angle;
  };

  std::vector<Planet> planets;
  float clockTime = 0.0f;
  float smoothEnergy = 0.0f;
  float smoothBass = 0.0f;
  float smoothSpark = 0.0f;

 public:
  void reset(uint32_t seed) override {
    (void)seed;
    planets.clear();
    planets.reserve(4);
    clockTime = 0.0f;
    smoothEnergy = 0.0f;
    smoothBass = 0.0f;
    smoothSpark = 0.0f;

    // Cobre
    planets.push_back({0.19f, 8.5f, 14.0f, 0.0f, 0.20f, false, {0.85f, 0.55f, 0.29f, 1.0f}, 0.8f});
    // Bronce
    planets.push_back({0.27f, 7.0f, 8.5f, 0.36f, 0.65f, false, {0.72f, 0.63f, 0.42f, 1.0f}, 2.3f});
    // Acero
    planets.push_back({0.35f, 9.5f, 11.2f, 0.42f, -0.50f, false, {0.44f, 0.62f, 0.77f, 1.0f}, 4.1f});
    // Jade (retrogrado)
    planets.push_back({0.42f, 6.5f, 6.8f, 0.15f, 1.10f, true, {0.37f, 0.75f, 0.63f, 1.0f}, 5.4f});
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    float targetSpark = f.music.active ? f.music.spark : 0.0f;
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));
    smoothSpark += (targetSpark - smoothSpark) * float(1.0 - std::exp(-dt * 15.0));

    // En silencio reposa en un tic-tac de reloj celestial sereno y majestuoso (~0.12f).
    // Con música la maquinaria de relojería se revoluciona al compás del ritmo.
    float audioDrive = 0.12f + smoothEnergy * 0.76f + smoothBass * 0.35f;
    float speedFactor = (f.reducedMotion ? 0.25f : 1.0f) * f.speed * audioDrive;
    clockTime += dt * speedFactor;

    for (auto& p : planets) {
      float dir = p.retrograde ? -1.0f : 1.0f;
      p.angle += dir * (6.2831853f / p.basePeriod) * dt * speedFactor;
    }
  }

  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float minDim = std::min(w, h);
    Vec2 center{w * 0.5f, h * 0.5f};
    float time = clockTime;
    float boost = std::clamp((0.85f + smoothEnergy * 0.35f) * f.intensity, 0.0f, 1.0f);

    // Sin fondo opaco: lienzo 100% transparente para efecto HUD / astrolabio flotante

    // 1. Barras diagonales estructurales de latón
    Paint crossbar;
    crossbar.color = {0.72f, 0.60f, 0.40f, std::clamp(0.38f * boost, 0.0f, 1.0f)};
    crossbar.strokeWidth = 1.5f;
    Path cross;
    for (int a = 0; a < 4; a++) {
      float ang = (float(a) * 3.14159265f * 0.5f) + 0.785398f;
      cross.moveTo(center.x + std::cos(ang) * minDim * 0.07f, center.y + std::sin(ang) * minDim * 0.07f);
      cross.lineTo(center.x + std::cos(ang) * minDim * 0.46f, center.y + std::sin(ang) * minDim * 0.46f);
    }
    c.path(cross, crossbar);

    // 2. Bisel exterior de la corona graduada con 96 muescas y glifos
    float crownTilt = (f.music.flow - 0.5f) * 0.16f;
    float outerR = minDim * 0.455f;
    float innerR = minDim * 0.415f;

    c.save();
    c.translate(center.x, center.y);
    c.rotate(crownTilt);

    // Aros del bisel
    Paint bezel;
    bezel.color = {0.85f, 0.72f, 0.48f, std::clamp(0.48f * boost, 0.0f, 1.0f)};
    bezel.strokeWidth = 1.8f;
    c.circle({0, 0}, outerR, bezel);
    c.circle({0, 0}, innerR, bezel);

    // 96 marcas graduadas en el bisel
    Path ticks;
    for (int i = 0; i < 96; i++) {
      float ang = (float(i) / 96.0f) * 6.2831853f;
      bool isMajor = (i % 8 == 0);
      float r0 = isMajor ? innerR : innerR + (outerR - innerR) * 0.45f;
      ticks.moveTo(std::cos(ang) * r0, std::sin(ang) * r0);
      ticks.lineTo(std::cos(ang) * outerR, std::sin(ang) * outerR);
    }
    Paint tickPaint;
    tickPaint.color = {0.85f, 0.72f, 0.48f, std::clamp(0.55f * boost, 0.0f, 1.0f)};
    tickPaint.strokeWidth = 1.0f;
    c.path(ticks, tickPaint);

    // 12 Glifos geométricos abstractos
    float midRingR = (outerR + innerR) * 0.5f;
    float glyphR = minDim * 0.012f;
    Path glyphsPath;
    for (int s = 0; s < 12; s++) {
      float ang = (float(s) / 12.0f) * 6.2831853f + 0.130899f;
      float gx = std::cos(ang) * midRingR;
      float gy = std::sin(ang) * midRingR;

      if (s % 3 == 0) {
        glyphsPath.moveTo(gx, gy - glyphR);
        glyphsPath.lineTo(gx + glyphR, gy);
        glyphsPath.lineTo(gx, gy + glyphR);
        glyphsPath.lineTo(gx - glyphR, gy);
        glyphsPath.close();
      } else if (s % 3 == 1) {
        glyphsPath.circle({gx, gy}, glyphR * 0.75f);
      } else {
        glyphsPath.moveTo(gx, gy - glyphR);
        glyphsPath.lineTo(gx + glyphR, gy + glyphR * 0.8f);
        glyphsPath.lineTo(gx - glyphR, gy + glyphR * 0.8f);
        glyphsPath.close();
      }
    }
    Paint glyphPaint;
    glyphPaint.color = {0.95f, 0.82f, 0.55f, std::clamp(0.70f * boost, 0.0f, 1.0f)};
    glyphPaint.strokeWidth = 1.2f;
    c.path(glyphsPath, glyphPaint);

    c.restore();

    // 3. Órbitas elípticas de latón grabadas con tren de engranajes
    for (size_t i = 0; i < planets.size(); i++) {
      const auto& p = planets[i];
      float orbitR = minDim * p.radiusRatio;

      c.save();
      c.translate(center.x, center.y);
      c.rotate(p.tiltAngle);

      Paint orbitPaint;
      orbitPaint.color = {0.75f, 0.65f, 0.45f, std::clamp(0.25f * boost, 0.0f, 1.0f)};
      orbitPaint.strokeWidth = 1.0f;

      Path orbitPath;
      float bAxis = orbitR * (1.0f - p.inclination * 0.32f);
      const int kEllipsePts = 48;
      for (int ep = 0; ep <= kEllipsePts; ep++) {
        float ea = (float(ep) / float(kEllipsePts)) * 6.2831853f;
        float ex = std::cos(ea) * orbitR;
        float ey = std::sin(ea) * bAxis;
        if (ep == 0) orbitPath.moveTo(ex, ey);
        else orbitPath.lineTo(ex, ey);
      }
      c.path(orbitPath, orbitPaint);

      // Engranaje anular dentado concéntrico en la órbita 2
      if (i == 1) {
        float gearR = orbitR * 0.96f;
        int teeth = 36;
        Path gearPath;
        for (int t = 0; t < teeth; t++) {
          float a0 = (float(t) / float(teeth)) * 6.2831853f + time * 0.12f;
          float a1 = a0 + (6.2831853f / float(teeth)) * 0.5f;
          float tr0 = gearR - 2.5f;
          float tr1 = gearR + 2.5f;
          gearPath.moveTo(std::cos(a0) * tr0, std::sin(a0) * tr0);
          gearPath.lineTo(std::cos(a0) * tr1, std::sin(a0) * tr1);
          gearPath.lineTo(std::cos(a1) * tr1, std::sin(a1) * tr1);
          gearPath.lineTo(std::cos(a1) * tr0, std::sin(a1) * tr0);
        }
        Paint gearPaint;
        gearPaint.color = {0.68f, 0.58f, 0.38f, std::clamp(0.35f * boost, 0.0f, 1.0f)};
        gearPaint.strokeWidth = 1.0f;
        c.path(gearPath, gearPaint);
      }

      c.restore();
    }

    // 4. Sol central de latón macizo con engranaje solar y corona flamígera
    float sunR = minDim * 0.052f;
    float bassGlow = std::clamp(0.35f + smoothBass * 0.65f, 0.0f, 1.0f);

    Paint sunCorona = Paint::radial(center, sunR * 2.8f,
      {{1.0f, 0.88f, 0.59f, std::clamp(0.85f * bassGlow * boost, 0.0f, 1.0f)},
       {0.85f, 0.55f, 0.29f, std::clamp(0.28f * bassGlow * boost, 0.0f, 1.0f)},
       {0, 0, 0, 0}}, {0.0f, 0.45f, 1.0f});
    sunCorona.blend = Blend::plus;
    c.circle(center, sunR * 2.8f, sunCorona);

    Paint sunBody = Paint::radial({center.x - sunR * 0.3f, center.y - sunR * 0.3f}, sunR,
      {Color::argb(0xfffff4d2), Color::argb(0xffd99b4a), Color::argb(0xff6b4820)},
      {0.0f, 0.6f, 1.0f});
    c.circle(center, sunR, sunBody);

    // Índice dorado giratorio esmaltado (reloj mecánico)
    c.save();
    c.translate(center.x, center.y);
    c.rotate(time * 0.25f);
    Path needle;
    needle.moveTo(0.0f, -sunR * 1.30f);
    needle.lineTo(sunR * 0.28f, 0.0f);
    needle.lineTo(0.0f, sunR * 0.55f);
    needle.lineTo(-sunR * 0.28f, 0.0f);
    needle.close();
    Paint needlePaint;
    needlePaint.color = {1.0f, 0.85f, 0.35f, bassGlow};
    needlePaint.blend = Blend::plus;
    c.path(needle, needlePaint);
    c.restore();

    // 5. Esferas planetarias con halo y destello spark
    for (const auto& p : planets) {
      float orbitR = minDim * p.radiusRatio;
      float cosTilt = std::cos(p.tiltAngle);
      float sinTilt = std::sin(p.tiltAngle);
      float squash = 1.0f - p.inclination * 0.32f;

      float lx = std::cos(p.angle) * orbitR;
      float ly = std::sin(p.angle) * orbitR * squash;
      float px = center.x + lx * cosTilt - ly * sinTilt;
      float py = center.y + lx * sinTilt + ly * cosTilt;

      float depthScale = 1.0f + std::sin(p.angle) * p.inclination * 0.22f;
      float pr = p.size * (minDim / 420.0f) * depthScale;

      // Halo atmosférico del planeta
      float haloR = pr * (2.6f + smoothSpark * 1.8f);
      Paint halo = Paint::radial({px, py}, haloR,
        {{p.color.r, p.color.g, p.color.b, std::clamp(0.55f * boost, 0.0f, 1.0f)},
         {p.color.r, p.color.g, p.color.b, 0.0f}}, {0.0f, 1.0f});
      halo.blend = Blend::plus;
      c.circle({px, py}, haloR, halo);

      // Esfera 3D iluminada hacia el sol central
      float dx = px - center.x;
      float dy = py - center.y;
      float dist = std::sqrt(dx * dx + dy * dy);
      if (dist < 1.0f) dist = 1.0f;
      float nx = dx / dist;
      float ny = dy / dist;

      float lightX = px - nx * pr * 0.42f;
      float lightY = py - ny * pr * 0.42f;
      Paint spherePaint = Paint::radial({lightX, lightY}, pr * 1.35f,
        {{1.0f, 0.99f, 0.96f, 1.0f},
         p.color,
         Color::argb(0xff120f0b)}, {0.0f, 0.45f, 1.0f});
      c.circle({px, py}, pr, spherePaint);

      // Destello en chispas agudas (90ms)
      if (smoothSpark > 0.02f) {
        Paint sparkPaint; sparkPaint.blend = Blend::plus;
        sparkPaint.color = {1.0f, 0.98f, 0.92f, std::clamp(smoothSpark * 0.90f * f.intensity, 0.0f, 1.0f)};
        c.circle({px, py}, pr * (1.0f + smoothSpark * 0.55f), sparkPaint);
      }
    }
  }
};

class Visual final : public Scene {
  float cloudTime = 0.0f;
  float warpOffset = 0.0f;
  float smoothBass = 0.0f;
  float smoothEnergy = 0.0f;
  float smoothSpark = 0.0f;

 public:
  void reset(uint32_t seed) override {
    (void)seed;
    cloudTime = 0.0f;
    warpOffset = 0.0f;
    smoothBass = 0.0f;
    smoothEnergy = 0.0f;
    smoothSpark = 0.0f;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    float targetSpark = f.music.active ? f.music.spark : 0.0f;
    smoothBass += (targetBass - smoothBass) * float(1.0 - std::exp(-dt * 6.0));
    smoothEnergy += (targetEnergy - smoothEnergy) * float(1.0 - std::exp(-dt * 5.0));
    smoothSpark += (targetSpark - smoothSpark) * float(1.0 - std::exp(-dt * 15.0));

    // En silencio las nubes flotan en una deriva reposada y etérea (~0.10f).
    // Con música la masa nubosa se arremolina y deforma con el audio.
    float audioDrive = 0.10f + smoothEnergy * 0.75f + smoothBass * 0.35f;
    float speedMult = (f.reducedMotion ? 0.25f : 1.0f) * f.speed * audioDrive;
    cloudTime += dt * speedMult;

    // Desplazamiento orgánico del dominio de ruido con los graves
    warpOffset += dt * (0.05f + smoothBass * 0.70f) * f.speed;
  }

  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    std::vector<float> u;
    u.reserve(6);
    u.push_back(cloudTime);
    u.push_back(warpOffset);
    u.push_back(smoothEnergy * 0.12f);
    u.push_back(smoothSpark * f.intensity);
    u.push_back(f.reducedMotion ? 1.0f : 0.0f);

    c.material("nubes", {0.0f, 0.0f, w, h}, u);
  }
};

